"""Turning spreadsheet rows into the per-sample series the plots consume."""
import math

from sed_stats.distributions.histogram import Histogram
from sed_stats.distributions.categorical import categorical_pdp, categorical_cdf
from sed_stats.distributions.numeric import (
    kde, kde_cdf, kernel_cdf, kernel_pdp, numeric_pdp, numeric_cdf,
    silverman_bandwidth,
)

from .config import MAX_BINS, PDP_POINTS, PDP_PAD_SIGMAS

# Header spellings that mark a column as an uncertainty on its neighbour, and
# the sigma level each one implies. None means the level is not stated, so the
# caller's assumption is used.
UNCERTAINTY_TOKENS = {
    "1s": 1.0, "1sigma": 1.0, "1se": 1.0, "1sd": 1.0, "s1": 1.0,
    "2s": 2.0, "2sigma": 2.0, "2se": 2.0, "2sd": 2.0, "s2": 2.0,
    "uncertainty": None, "uncert": None, "unc": None,
    "error": None, "err": None, "sigma": None,
    "sd": None, "std": None, "stdev": None, "stddev": None, "se": None,
    "": None,  # a bare "±" normalizes to empty
}


# A sigma glyph is alphanumeric, so it survives the alnum filter and has to be
# folded to "s" for "± 1σ" to read the same as "1s".
_SIGMA_GLYPHS = str.maketrans({"σ": "s", "ς": "s", "Σ": "s"})


def _normalize(name):
    """Lowercase, alphanumerics only, so '± 1σ' and '1_S' compare equal."""
    folded = str(name).lower().translate(_SIGMA_GLYPHS)
    return "".join(c for c in folded if c.isalnum())


def _uncertainty_level(name):
    """The sigma level a header implies, or False if it isn't an uncertainty."""
    token = _normalize(name)
    if token in UNCERTAINTY_TOKENS:
        return UNCERTAINTY_TOKENS[token]
    return False


def find_uncertainty_column(keys, attribute):
    """
    The column carrying `attribute`'s uncertainty, and the sigma level it states.

    Recognises two conventions: a suffixed name ("age_1s", "size_mm error"),
    and a bare uncertainty column sitting immediately to the right of its
    measurement, which is how most detrital spreadsheets are laid out.

    Returns:
        (column_name, sigma_level) where sigma_level is 1.0 / 2.0 when the
        header states it and None when it does not, or (None, None)
    """
    prefix = _normalize(attribute)

    for key in keys:
        if key == attribute:
            continue
        token = _normalize(key)
        if token.startswith(prefix) and len(token) > len(prefix):
            level = _uncertainty_level(token[len(prefix):])
            if level is not False:
                return key, level

    if attribute in keys:
        index = keys.index(attribute)
        if index + 1 < len(keys):
            neighbour = keys[index + 1]
            level = _uncertainty_level(neighbour)
            if level is not False:
                return neighbour, level

    return None, None


def detect_columns(rows):
    """
    First column is the sample ID, second the grain ID, rest are dimensions.

    Uncertainty columns are pulled out of the dimension list: they describe a
    measurement rather than being one, and offering "1s" as something to graph
    on its own is just noise.
    """
    if not rows:
        return None, None, []
    keys = list(rows[0].keys())
    sample_col = keys[0] if keys else None
    id_col = keys[1] if len(keys) > 1 else None

    candidates = keys[2:]
    spoken_for = set()
    for attribute in candidates:
        if attribute in spoken_for:
            continue
        column, _ = find_uncertainty_column(keys, attribute)
        if column is not None and column != attribute:
            spoken_for.add(column)

    return sample_col, id_col, [k for k in candidates if k not in spoken_for]


def sample_names(rows, sample_col):
    """Distinct sample names in spreadsheet order."""
    names = []
    for row in rows:
        name = str(row.get(sample_col, "") or "").strip()
        if name and name not in names:
            names.append(name)
    return names


def values_by_sample(rows, sample_col, attribute, only_samples=None):
    """Non-empty attribute values grouped by sample, preserving sample order."""
    grouped = {}
    for row in rows:
        sample = str(row.get(sample_col, "") or "").strip()
        value = row.get(attribute, "")
        if not sample or value in ("", None):
            continue
        if only_samples is not None and sample not in only_samples:
            continue
        grouped.setdefault(sample, []).append(value)
    return grouped


def is_numeric_column(rows, column):
    """
    Whether every non-empty value in `column` parses as a number.

    Matches how attribute_series decides: it attempts the numeric path and
    falls back to the categorical one on the first value that won't convert.
    """
    seen = False
    for row in rows:
        value = row.get(column, "")
        if value in ("", None):
            continue
        try:
            float(value)
        except (TypeError, ValueError):
            return False
        seen = True
    return seen


DATE_SCAN = 200           # values read before a column is judged
DATE_HEAD = 8             # a column is first judged on this many values, so a column of text is dropped cheaply
DATE_SHARE = 0.9          # the share of a column's values that must read as dates for it to count as one


def is_date_column(rows, column):
    """
    Whether the column holds dates: at least DATE_SHARE of its non-empty values (the first DATE_SCAN of
    them) read as dates, and none is a plain number (a year or an Excel serial number is not taken for
    one). A few unreadable entries do not stop a column of dates being offered; the block that uses it
    leaves them out and says so. The order of day and month is not guessed: the column counts if it
    reads month first, or day first, for that share of its values.

    This runs each time a dialog opens, and reading a value that is not a date is slow (every format
    is tried and fails), so the first DATE_HEAD values decide whether the rest are worth reading.
    """
    from sed_stats import dates as dt
    values = []
    for row in rows:
        value = row.get(column, "")
        if value in ("", None):
            continue
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return False
        values.append(value)
        if len(values) >= DATE_SCAN:
            break
    if not values:
        return False
    head = values[:DATE_HEAD]
    for day_first in (False, True):
        if sum(dt.parse_date(v, day_first) is not None for v in head) < DATE_SHARE * len(head):
            continue
        if sum(dt.parse_date(v, day_first) is not None for v in values) >= DATE_SHARE * len(values):
            return True
    return False


def date_columns(rows, columns):
    """The subset of `columns` holding dates (see `is_date_column`)."""
    return {column for column in columns if is_date_column(rows, column)}


def numeric_columns(rows, columns):
    """The subset of `columns` holding numbers."""
    return {column for column in columns if is_numeric_column(rows, column)}


def pairs_by_sample(rows, sample_col, attribute, uncertainty_col, only_samples=None):
    """
    (value, uncertainty) pairs grouped by sample, keeping only numeric rows.

    A row whose uncertainty is missing or unparseable keeps its value with an
    uncertainty of 0; kernel_density floors those rather than dropping the
    measurement, since the value itself is still good data.
    """
    grouped = {}
    for row in rows:
        sample = str(row.get(sample_col, "") or "").strip()
        value = row.get(attribute, "")
        if not sample or value in ("", None):
            continue
        if only_samples is not None and sample not in only_samples:
            continue
        try:
            numeric_value = float(value)
        except (TypeError, ValueError):
            raise ValueError(f"'{attribute}' is not numeric")
        try:
            sigma = abs(float(row.get(uncertainty_col, "")))
        except (TypeError, ValueError):
            sigma = 0.0
        grouped.setdefault(sample, []).append((numeric_value, sigma))
    return grouped


def categories_of(rows, sample_col, attribute, only_samples=None):
    """Sorted distinct values of a categorical attribute among the chosen samples."""
    return sorted({str(v).strip()
                   for values in values_by_sample(
                       rows, sample_col, attribute, only_samples).values()
                   for v in values})


def paired_by_sample(rows, sample_col, x_attribute, y_attribute,
                     only_samples=None, sigma_in=1.0,
                     x_categories=None, y_categories=None):
    """
    Paired x/y measurements and their uncertainties, grouped by sample.

    A bivariate distribution needs both coordinates for the same grain, so a
    row missing either one is dropped — unlike the univariate path, where each
    column stands alone.

    A categorical attribute is named by passing its category list as
    `x_categories` / `y_categories`: its values come back as positions in that
    list, with an uncertainty of 0, and no uncertainty column is looked for.

    Returns:
        {sample: (xs, ys, x_sigmas, y_sigmas)} with equal-length lists

    Raises:
        ValueError: if an attribute not declared categorical is not numeric
    """
    keys = list(rows[0].keys()) if rows else []
    x_position = None if x_categories is None else {c: i for i, c in enumerate(x_categories)}
    y_position = None if y_categories is None else {c: i for i, c in enumerate(y_categories)}
    x_uncertainty, x_level = ((None, None) if x_position is not None
                              else find_uncertainty_column(keys, x_attribute))
    y_uncertainty, y_level = ((None, None) if y_position is not None
                              else find_uncertainty_column(keys, y_attribute))
    x_scale = x_level or sigma_in or 1.0
    y_scale = y_level or sigma_in or 1.0

    def read_sigma(row, column, scale):
        if not column:
            return 0.0
        try:
            return abs(float(row.get(column, ""))) / scale
        except (TypeError, ValueError):
            return 0.0

    grouped = {}
    for row in rows:
        sample = str(row.get(sample_col, "") or "").strip()
        if not sample:
            continue
        if only_samples is not None and sample not in only_samples:
            continue
        x_raw = row.get(x_attribute, "")
        y_raw = row.get(y_attribute, "")
        if x_raw in ("", None) or y_raw in ("", None):
            continue
        try:
            x_value = (float(x_position[str(x_raw).strip()]) if x_position is not None
                       else float(x_raw))
            y_value = (float(y_position[str(y_raw).strip()]) if y_position is not None
                       else float(y_raw))
        except KeyError:
            continue  # a category outside the chosen samples
        except (TypeError, ValueError):
            raise ValueError(
                f"'{x_attribute}' and '{y_attribute}' must both be numeric "
                f"or declared categorical")

        entry = grouped.setdefault(sample, ([], [], [], []))
        entry[0].append(x_value)
        entry[1].append(y_value)
        entry[2].append(read_sigma(row, x_uncertainty, x_scale))
        entry[3].append(read_sigma(row, y_uncertainty, y_scale))
    return grouped


def nice_bin_size(vmin, vmax, target_bins=30):
    """A round bin width (1/2/2.5/5 x 10^k) giving roughly target_bins bins."""
    span = (vmax - vmin) or abs(vmin) or 1
    raw = span / target_bins
    magnitude = 10 ** math.floor(math.log10(raw))
    for m in (1, 2, 2.5, 5, 10):
        if raw <= m * magnitude:
            return m * magnitude
    return raw


def _numeric_series(grouped, view, bin_size):
    """Per-sample histograms on a shared bin grid so all series align."""
    numeric = {s: [float(v) for v in vals] for s, vals in grouped.items()}
    all_values = [v for vals in numeric.values() for v in vals]

    if bin_size is None or (max(all_values) - min(all_values)) / bin_size > MAX_BINS:
        bin_size = nice_bin_size(min(all_values), max(all_values))

    first_bin = math.floor(min(all_values) / bin_size)
    last_bin = math.floor(max(all_values) / bin_size)
    bin_starts = [(first_bin + i) * bin_size for i in range(last_bin - first_bin + 1)]

    labels = [f"{b:g}" for b in bin_starts]
    series = []
    for sample, vals in numeric.items():
        counts = {str(b): 0 for b in bin_starts}
        for v in vals:
            index = math.floor(v / bin_size) - first_bin
            counts[str(bin_starts[index])] += 1
        histogram = Histogram(counts)

        if view == "histogram":
            data = list(histogram.counts)
        else:
            distribution = numeric_cdf(histogram) if view == "cdf" else numeric_pdp(histogram)
            data = [float(p) for p in distribution.probabilities]
        series.append((sample, data))
    return labels, series


def _categorical_series(grouped, view):
    """Per-sample histograms over the shared, sorted category set."""
    categories = sorted({str(v) for vals in grouped.values() for v in vals})
    series = []
    for sample, vals in grouped.items():
        str_vals = [str(v) for v in vals]
        histogram = Histogram({c: str_vals.count(c) for c in categories})

        if view == "histogram":
            data = list(histogram.counts)
        else:
            distribution = categorical_cdf(histogram) if view == "cdf" else categorical_pdp(histogram)
            data = [float(p) for p in distribution.probabilities]
        series.append((sample, data))
    return categories, series


def _kernel_grid(pairs, bin_size):
    """
    A shared x grid for kernel PDPs, wide and fine enough for every sample.

    Padded by PDP_PAD_SIGMAS so the widest kernel's tails are not clipped, and
    stepped finely enough to resolve the narrowest one — a grid built for the
    histogram's ~30 bins would turn a precise measurement into a single spike.
    """
    values = [v for v, _ in pairs]
    sigmas = [s for _, s in pairs if s > 0]

    low = min(v - PDP_PAD_SIGMAS * s for v, s in pairs)
    high = max(v + PDP_PAD_SIGMAS * s for v, s in pairs)
    if high <= low:
        # Every measurement identical and exact; give the spike somewhere to sit.
        pad = abs(low) * 0.01 or 1.0
        low, high = low - pad, high + pad
    span = high - low

    if bin_size and bin_size > 0:
        step = bin_size
    else:
        step = span / PDP_POINTS
        if sigmas:
            step = min(step, min(sigmas) / 2)

    n_points = int(span / step) + 1
    if n_points > MAX_BINS:
        n_points = MAX_BINS
        step = span / (n_points - 1)
    n_points = max(n_points, 2)

    return [low + i * step for i in range(n_points)], step


def _kernel_series(grouped, view, bin_size):
    """Per-sample kernel PDPs/CDFs on one shared grid."""
    all_pairs = [pair for pairs in grouped.values() for pair in pairs]
    x_values, step = _kernel_grid(all_pairs, bin_size)
    labels = [f"{x:g}" for x in x_values]

    series = []
    for sample, pairs in grouped.items():
        values = [v for v, _ in pairs]
        sigmas = [s for _, s in pairs]
        build = kernel_cdf if view == "cdf" else kernel_pdp
        distribution = build(values, sigmas, x_values, sigma_floor=step / 2)
        series.append((sample, [float(p) for p in distribution.probabilities]))
    return labels, series


def _kde_series(grouped, view, bin_size, bandwidth):
    """
    Per-sample KDEs on one shared grid, all using the same bandwidth.

    One bandwidth for every sample is the point: the curves are compared to
    each other downstream, so smoothing them differently would put a
    difference in the metric that isn't in the data.
    """
    numeric = {}
    for sample, values in grouped.items():
        numeric[sample] = [float(v) for v in values]

    pooled = [v for values in numeric.values() for v in values]
    if bandwidth is None or bandwidth <= 0:
        bandwidth = float(silverman_bandwidth(pooled))

    x_values, _ = _kernel_grid([(v, bandwidth) for v in pooled], bin_size)
    labels = [f"{x:g}" for x in x_values]

    series = []
    for sample, values in numeric.items():
        build = kde_cdf if view == "cdf" else kde
        distribution = build(values, bandwidth, x_values)
        series.append((sample, [float(p) for p in distribution.probabilities]))
    return labels, series, bandwidth


def attribute_series(rows, sample_col, attribute, view, bin_size, only_samples=None,
                     density="auto", sigma_in=1.0, bandwidth=None):
    """
    Returns (labels, [(sample, data), ...]) for one dimension across samples.

    Histograms are counts, so they always bin. For a PDF/CDF, `density`
    chooses how the curve is built:

        "auto" - spread each measurement by its own uncertainty column (a PDP),
                 falling back to bins when the dimension has no such column
        "kde"  - one Gaussian per measurement, all `bandwidth` wide
        "bins" - bin, whatever columns exist

    Args:
        sigma_in: Sigma level of an uncertainty column that does not state its
                  own (a bare "1s"/"2s" header overrides this)
        bandwidth: KDE width; None picks one by Silverman's rule
    """
    if view in ("pdf", "cdf"):
        if density == "auto":
            labels, series = _uncertainty_series(
                rows, sample_col, attribute, view, bin_size, only_samples, sigma_in)
            if series:
                return labels, series
        elif density == "kde":
            grouped = values_by_sample(rows, sample_col, attribute, only_samples)
            if grouped:
                try:
                    labels, series, _ = _kde_series(grouped, view, bin_size, bandwidth)
                    return labels, series
                except (TypeError, ValueError):
                    pass  # categorical dimension; bin it below

    grouped = values_by_sample(rows, sample_col, attribute, only_samples)
    if not grouped:
        return [], []
    try:
        return _numeric_series(grouped, view, bin_size)
    except (TypeError, ValueError):
        return _categorical_series(grouped, view)


def _uncertainty_series(rows, sample_col, attribute, view, bin_size,
                        only_samples, sigma_in):
    """The kernel path, or ([], []) when it does not apply to this dimension."""
    if not rows:
        return [], []

    column, stated_level = find_uncertainty_column(list(rows[0].keys()), attribute)
    if column is None:
        return [], []

    try:
        grouped = pairs_by_sample(rows, sample_col, attribute, column, only_samples)
    except ValueError:
        # Categorical dimension; the uncertainty column was a false positive.
        return [], []
    if not grouped:
        return [], []

    # A stated "2s" header wins over the caller's assumption. Bandwidths are
    # always 1 sigma.
    level = stated_level or sigma_in or 1.0
    if level != 1.0:
        grouped = {sample: [(v, s / level) for v, s in pairs]
                   for sample, pairs in grouped.items()}

    if not any(s > 0 for pairs in grouped.values() for _, s in pairs):
        # Column present but empty; binning is the honest fallback.
        return [], []

    return _kernel_series(grouped, view, bin_size)


def series_for(rows, sample_col, dimension, view, opts):
    """attribute_series with the options every tool's wizard collects."""
    return attribute_series(
        rows, sample_col, dimension, view,
        opts.get("bin_size"), opts.get("samples"),
        density=opts.get("density", "auto"),
        sigma_in=opts.get("sigma_in", 1.0),
        bandwidth=opts.get("bandwidth"),
    )

scripts/dashboard/node_dialog.py:
"""
The dialog that adds a node to the workflow, or edits one already there.

Nothing in it is specific to a node: it is built from the node's ports and
option `Field`s. The inputs panel wires each port to a source; the data and
option panels follow, and their choices — which columns, which samples — are
drawn from whatever the first input will deliver, so a step after a Grain PCA
offers PC1 and PC2 and a Mixture offers the samples its Distribution kept.
"""
from antioch.dom import DOM
from antioch.elements import Div, Input, Option, P, Select
from antioch.event import when
from antioch.macros import Modal

from ui_lib import CheckboxGroup, Wizard, WizardPanel, labeled

from .nodes import (
    CHECKBOX, DATA_PAGE, DIMENSION, DIMENSIONS, NUMBER, OPTIONS_PAGE, SAMPLE,
    SAMPLES, SELECT, TEXT, Context, context_of, likely_column,
)
from .combine import unique_names
from .ports import PortEditor

MODAL_STYLE = {"max-width": "760px", "width": "92vw", "min-width": "0"}
NOTE_STYLE = {"color": "#555", "font-size": "13px", "margin": "0 0 14px 0"}


class NodeDialog:
    """
    Usage:
        dialog = NodeDialog(node)
        dialog.open(context)                 # add a step
        dialog.open(context, step=step)      # edit one

    `context` supplies what the dialog cannot know:
        choices(node, port, before)  -> [(source id, label)] the port could read
        batch(source id)             -> the batch it would receive
        type_of(source id)           -> its data type
        submit(node key, opts, inputs, step id or None)
    """

    def __init__(self, node):
        self.node = node
        self._context = None
        self._data = Context()
        self._step = None
        self._widgets = {}      # field key -> (row, control, field)
        self._ports = {}        # port name -> PortEditor
        self._port_rows = {}
        self._port_labeled = {}
        self._title = Input("text", placeholder=f"e.g. {node.label} of …",
                            style={"width": "260px"})

        panels = self._build_panels()
        self.wizard = Wizard(submit_text="Add to workflow", panels=panels)
        self.wizard.element.style.update({
            "margin-top": "0", "border": "none", "border-radius": "0"})

        @when(self.wizard.events.submit)
        def on_submit(sender, *args):
            self._submit()

        self.modal = Modal(title=node.label, modal_style=MODAL_STYLE)
        self.modal.set_content(self.wizard.element)
        DOM.add(self.modal.element)

    # ------------------------------------------------------------ construction

    def _build_panels(self):
        node = self.node
        inputs = Div()
        if node.description:
            inputs.add(P(node.description, style=dict(NOTE_STYLE)))
        for port in node.spec.ports:
            holder = Div()
            self._port_rows[port.name] = holder
            row = labeled(port.label or port.name, holder, port.hint or None)
            self._port_labeled[port.name] = row
            inputs.add(row)
        inputs.add(labeled("Title", self._title,
                           "Optional; names the step and its card"))

        pages = {DATA_PAGE: [], OPTIONS_PAGE: []}
        for f in node.fields:
            control = self._control(f)
            row = labeled(f.label, control.element if hasattr(control, "element")
                          else control, f.hint or None)
            self._widgets[f.key] = (row, control, f)
            pages[f.page].append(row)

        panels = [WizardPanel("Inputs", inputs,
                              f"Choose what the {node.label.lower()} reads.")]
        if pages[DATA_PAGE]:
            panels.append(WizardPanel(
                "Data", Div(*pages[DATA_PAGE]),
                "Choose which of the input's samples and dimensions to use."))
        if pages[OPTIONS_PAGE]:
            panels.append(WizardPanel("Options", Div(*pages[OPTIONS_PAGE]),
                                      "Configure how it runs."))
        return panels

    def _control(self, f):
        if f.kind == SELECT:
            select = Select()
            select.on('change', lambda e: self._refresh_visibility())
            return select
        if f.kind in (DIMENSION, SAMPLE):
            return Select()
        if f.kind == CHECKBOX:
            box = Input("checkbox")
            box._dom_element.checked = bool(f.default)
            box.on('change', lambda e: self._refresh_visibility())
            return box
        if f.kind == NUMBER:
            return Input("number", placeholder="auto", style={"width": "90px"},
                         **({"step": "any"} if f.signed else {}))
        if f.kind == TEXT:
            return Input("text", style={"width": "320px"})
        if f.kind == DIMENSIONS:
            return CheckboxGroup(all_checked=False,
                                 empty_text="No dimensions in this input",
                                 on_change=lambda values: self._refresh_visibility())
        if f.kind == SAMPLES:
            return CheckboxGroup(all_checked=not f.unchecked,
                                 empty_text="No samples in this input",
                                 on_change=lambda values: self._refresh_visibility())
        raise ValueError(f"Unknown field kind '{f.kind}'")

    # --------------------------------------------------------------- opening

    def open(self, context, step=None, preset=None):
        """
        Show the dialog to add a step, or to edit `step`.

        `preset` is a source id to start the first port that can read it on,
        instead of the usual default.
        """
        self._context = context
        self._step = step
        self.wizard.set_status("")
        self.wizard.set_submit_text(
            "Save changes" if step else getattr(context, "submit_label", "Add to workflow"))
        # Run on the spreadsheet alone, there is nothing to choose to read.
        hide = getattr(context, "single_input", False)
        for row in self._port_labeled.values():
            row.style.display = "none" if hide else "block"
        self._title.value = (step.options.get("title", "") if step else "")

        before = step.id if step else None
        preset_kind = context.type_of(preset) if preset else None
        for port in self.node.spec.ports:
            choices = context.choices(self.node, port, before)
            chosen = step.inputs.get(port.name) if step else None
            if (preset and not step and port.accepts(preset_kind)
                    and preset in [source for source, _ in choices]):
                chosen, preset = [preset], None       # used: later ports take their defaults
            editor = PortEditor(
                port, choices, chosen, on_change=lambda ids: self._rewired(),
                empty_text=self._nothing_to_read(port))
            self._ports[port.name] = editor
            holder = self._port_rows[port.name]
            holder._dom_element.innerHTML = ""
            holder.add(editor.element)

        # A new block starts clean — it is a fresh piece, not the last one
        # reused — while editing shows the step's own values.
        self._reset()
        self._refresh_data()
        if step:
            self._write(step.options)
        self._refresh_visibility()
        self.modal.open()
        return self

    def _reset(self):
        """Put every control back to its starting state."""
        for _, control, f in self._widgets.values():
            if f.kind == SAMPLES:
                control.set_all(not f.unchecked)
            elif f.kind == DIMENSIONS:
                control.set_all(False)
            elif f.kind == CHECKBOX:
                control._dom_element.checked = bool(f.default)
            elif f.kind in (NUMBER, TEXT):
                # A field's default is shown, so the dialog says what will be used (and a block
                # with typed-in numbers, like the Thiem drawdown, opens ready to run)
                control.value = _shown(f.default)
            else:
                control.clear()      # refilled, on its default, with the data

    @staticmethod
    def _nothing_to_read(port):
        from workflow_lib import TYPE_LABELS
        kinds = " or ".join(TYPE_LABELS[t].lower() for t in port.types)
        return f"Nothing to connect: add a step that produces {kinds} first."

    # ------------------------------------------------------------- the data

    def _rewired(self):
        self._refresh_data()
        self._refresh_visibility()

    def _first_port_with_sources(self):
        for port in self.node.spec.ports:
            editor = self._ports.get(port.name)
            if editor and editor.sources():
                return port, editor.sources()
        return None, []

    def _describe_inputs(self):
        """
        What the first input delivers. A port wired to several sources offers the
        samples of all of them, named as `combine` will name them.
        """
        _, sources = self._first_port_with_sources()
        if not sources:
            return Context()
        parts = [context_of(self._context.type_of(s), self._context.batch(s))
                 for s in sources]
        merged = parts[0]
        if len(parts) > 1:
            merged.samples = [name for names in unique_names([p.samples for p in parts])
                              for name in names]
        return merged

    def _refresh_data(self):
        """Offer the columns and samples of whatever the first input delivers."""
        self.wizard.set_status("")
        try:
            self._data = self._describe_inputs()
        except Exception as error:
            self._data = Context()
            self.wizard.set_status(f"Could not prepare that input: {error}")

        data = self._data
        for _, control, f in self._widgets.values():
            if f.kind == SAMPLES:
                control.set_options(list(data.samples))
            elif f.kind in (DIMENSIONS, DIMENSION):
                usable = [d for d in data.dimensions
                          if not f.numeric_only or d in data.numeric
                          or (f.dates and d in data.dates)]
                if f.kind == DIMENSIONS:
                    control.set_options(usable)
                else:
                    _fill(control, {d: d for d in usable}, nth=f.nth,
                          default=likely_column(usable, f.like) if f.like else None,
                          empty="No dimensions in this input")
            elif f.kind == SAMPLE:
                _fill(control, {s: s for s in data.samples},
                      empty="No samples in this input")
            elif f.kind == SELECT:
                self._fill_select(control, f, data)

    def _fill_select(self, control, f, data):
        """Fill a SELECT from its field; a `dynamic` one sees the current options."""
        if callable(f.choices):
            choices = f.choices(data, self.read()) if f.dynamic else f.choices(data)
        else:
            choices = f.choices
        _fill(control, {str(k): v for k, v in choices.items()},
              default=None if f.default is None else str(f.default))

    # ------------------------------------------------------------ the values

    def read(self):
        """The options as the dialog stands, keyed like a step's saved options."""
        opts = {"title": self._title.value.strip()}
        for key, (_, control, f) in self._widgets.items():
            if f.kind in (SAMPLES, DIMENSIONS):
                opts[key] = control.values()
            elif f.kind == CHECKBOX:
                opts[key] = bool(control._dom_element.checked)
            elif f.kind == NUMBER:
                opts[key] = _number(control.value) if f.signed else _positive(control.value)
            elif f.kind == TEXT:
                opts[key] = control.value.strip() or None
            else:
                value = control.value or None
                opts[key] = f.cast(value) if (f.cast and value is not None) else value
        return opts

    def _write(self, opts):
        """Put saved options back into the controls, for editing."""
        for key, (_, control, f) in self._widgets.items():
            if key not in opts:
                continue
            value = opts[key]
            if f.kind in (SAMPLES, DIMENSIONS):
                _check_only(control, value)
            elif f.kind == CHECKBOX:
                control._dom_element.checked = bool(value)
            elif f.kind in (NUMBER, TEXT):
                control.value = "" if value is None else str(value)
            elif value is not None:
                control.value = str(value)

    def _refresh_visibility(self):
        """Show a field only while its `when` holds for the options chosen."""
        opts = self.read()
        for _, (row, control, f) in self._widgets.items():
            row.style.display = "block" if (not f.when or f.when(opts)) else "none"
            if f.dynamic and f.kind == SELECT:
                self._fill_select(control, f, self._data)

    # ---------------------------------------------------------------- submit

    def _submit(self):
        node = self.node
        inputs = {}
        for port in node.spec.ports:
            ids = self._ports[port.name].sources()
            if not ids and not port.optional:
                self.wizard.set_status(
                    f"'{port.label or port.name}' has nothing connected.")
                return
            inputs[port.name] = ids
        opts = self.read()
        problem = node.validate(opts, self._data) if node.validate else None
        if problem:
            self.wizard.set_status(problem)
            return
        step = self._step
        self.wizard.set_status("")
        self.modal.close()
        self._context.submit(node.key, opts, inputs, step.id if step else None)


def _shown(default):
    """A field's default as the text of its box: "" for none, 60 not 60.0."""
    if default is None:
        return ""
    if isinstance(default, float) and default == int(default) and abs(default) < 1e15:
        return str(int(default))
    return str(default)


def _fill(select, choices, nth=0, default=None, empty="Nothing to choose"):
    """
    Replace a Select's options with `{value: label}`, keeping the current choice
    if it is still on offer; otherwise `default`, else the `nth` option.
    """
    previous = select.value
    select.clear()
    if not choices:
        select.add(Option(empty, value=""))
        return
    for value, label in choices.items():
        select.add(Option(str(label), value=value))
    keys = list(choices)
    if previous in keys:
        select.value = previous
    elif default is not None and default in keys:
        select.value = default
    else:
        select.value = keys[min(nth, len(keys) - 1)]


def _check_only(group, values):
    """Check exactly `values` in a CheckboxGroup."""
    wanted = set(values or [])
    group.set_all(False)
    for value, box in group._boxes.items():
        box._dom_element.checked = value in wanted
    group._changed()


def _number(value):
    """A float from a number input, or None when blank or invalid."""
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _positive(value):
    """A positive float from a number input, or None when blank or invalid."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if number > 0 else None

scripts/dashboard/nodes/__init__.py:
"""
Every node a workflow can use, and the menu that lists them.

Nodes come in two kinds: compute nodes (`compute`) that turn one type of data
into another, and graphs (`graphs`) that end a chain by drawing it.
"""
from .base import (
    CHECKBOX, Context, DATA_PAGE, DIMENSION, DIMENSIONS, Field, NUMBER, Node,
    OPTIONS_PAGE, SAMPLE, SAMPLES, SELECT, StepOutput, TEXT, context_of, likely_column,
)
from .compute import COMPUTE_NODES
from .graphs import GRAPH_NODES
from .groundwater import GROUNDWATER_NODES
from .hydro import HYDRO_NODES
from .isotope import ISOTOPE_NODES
from .isotope_plots import ISOTOPE_PLOT_NODES
from .maps import MAP_NODES
from .outlines import table_outlines
from .tablework import TABLE_NODES

NODES = {node.key: node for node in COMPUTE_NODES + [table_outlines] + TABLE_NODES + ISOTOPE_NODES + ISOTOPE_PLOT_NODES + HYDRO_NODES + GROUNDWATER_NODES + MAP_NODES + GRAPH_NODES}

# Menu order: the categories a node can name, and what each is for.
CATEGORIES = ("Describe", "Transform", "Compare", "Model", "Groundwater", "Map", "Graph")


def specs():
    """{key: NodeSpec} for the workflow engine."""
    return {key: node.spec for key, node in NODES.items()}


def compute(step, inputs):
    """The engine's compute callback: run a compute step's node."""
    return NODES[step.tool].run(inputs, step.options)


def render(step, inputs):
    """The engine's render callback: run a graph step's node."""
    return NODES[step.tool].run(inputs, step.options)


def menu():
    """{category: [node keys]} in menu order, skipping empty categories."""
    found = {}
    for category in CATEGORIES:
        keys = [n.key for n in NODES.values()
                if n.spec.category == category and getattr(n, "listed", True)]
        if keys:
            found[category] = keys
    return found


__all__ = ["CHECKBOX", "CATEGORIES", "Context", "DATA_PAGE", "DIMENSION",
           "DIMENSIONS", "Field", "NODES", "NUMBER", "Node", "OPTIONS_PAGE",
           "SAMPLE", "SAMPLES", "SELECT", "StepOutput", "TEXT", "compute",
           "context_of", "likely_column", "menu", "render", "specs"]

scripts/dashboard/recovery.py:
"""
A recovery copy of the work in progress, kept in the browser's IndexedDB.

IndexedDB rather than localStorage: a project with thousands of grains is
megabytes, past what localStorage will hold, and IndexedDB stores it without
blocking the page. One entry is kept, the latest unsaved state, written while
there are unsaved changes and cleared once they are saved.

Everything here is best effort. Private windows, blocked site data and a full
disk all make IndexedDB fail, and losing the recovery copy must never get in
the way of the app, so every failure becomes "nothing stored".
"""
import js
from pyodide.ffi import to_js

_SHIM_ID = "sedstats-recovery-shim"
_SHIM_NAME = "__sedStatsRecovery"

_SHIM = """
(function () {
  if (window.__sedStatsRecovery) return;
  const DB = 'sedstats', STORE = 'recovery', KEY = 'latest';

  function open() {
    return new Promise(function (resolve, reject) {
      const request = indexedDB.open(DB, 1);
      request.onupgradeneeded = function () { request.result.createObjectStore(STORE); };
      request.onsuccess = function () { resolve(request.result); };
      request.onerror = function () { reject(request.error); };
      request.onblocked = function () { reject(new Error('IndexedDB is blocked')); };
    });
  }

  // Resolves once the transaction has committed, not merely once the request
  // was queued, so a caller that awaits a write knows it is on disk.
  function run(mode, work) {
    return open().then(function (db) {
      return new Promise(function (resolve, reject) {
        const tx = db.transaction(STORE, mode);
        const request = work(tx.objectStore(STORE));
        tx.oncomplete = function () { db.close(); resolve(request && request.result); };
        tx.onerror = tx.onabort = function () { db.close(); reject(tx.error); };
      });
    });
  }

  window.__sedStatsRecovery = {
    put: function (value) { return run('readwrite', function (s) { return s.put(value, KEY); }); },
    get: function () { return run('readonly', function (s) { return s.get(KEY); }); },
    clear: function () { return run('readwrite', function (s) { return s.delete(KEY); }); },
  };

  // Read by the beforeunload handler below; Python keeps it current.
  window.__sedUnsaved = false;
  window.addEventListener('beforeunload', function (event) {
    if (window.__sedUnsaved) {
      event.preventDefault();
      event.returnValue = '';
      return '';
    }
  });
})();
"""


def _ensure_shim():
    if not js.document.getElementById(_SHIM_ID):
        script = js.document.createElement("script")
        script.id = _SHIM_ID
        script.textContent = _SHIM
        js.document.head.appendChild(script)
    return getattr(js.window, _SHIM_NAME, None)


def set_unsaved_flag(unsaved):
    """Tell the browser whether leaving the page would lose work."""
    try:
        _ensure_shim()
        js.window.__sedUnsaved = bool(unsaved)
    except Exception:
        pass


class RecoveryStore:
    """
    The one recovery entry.

    An entry is {"text", "name", "file_id", "saved_at", "rows", "outputs"}:
    `text` is a complete project (see `project_lib`), so restoring is just
    opening it.
    """

    async def put(self, entry):
        """Store `entry`; returns whether it was written."""
        try:
            shim = _ensure_shim()
            await shim.put(to_js(entry, dict_converter=js.Object.fromEntries))
            return True
        except Exception:
            return False

    async def get(self):
        """The stored entry as a dict, or None."""
        try:
            shim = _ensure_shim()
            found = await shim.get()
            # A missing key is JS undefined or null; a real entry is an object.
            if not found or not hasattr(found, "to_py"):
                return None
            entry = found.to_py()
            return entry if isinstance(entry, dict) and entry.get("text") else None
        except Exception:
            return None

    async def clear(self):
        try:
            shim = _ensure_shim()
            await shim.clear()
            return True
        except Exception:
            return False

scripts/dashboard/scatter.py:
"""
Scatterplots: raw grain measurements, coloured by sample.

Every other analysis in the app shows a distribution — something estimated from
the grains. This shows the grains. It is the plot to reach for when a density
looks wrong and you want to know whether the data or the kernel is responsible.

`points_from_table` is the step that lifts two columns into `Points`, and
`draw_points` is the graph that plots any Points — grains, an ordination's
samples — with polygons (a hull, a contour) over them.
"""
import math

from antioch.elements import Div, P

from plot_lib import (
    SCATTER_CAP, categorical_color, marker_trace, scatter_trace, series_symbol,
)
from workflow_lib import NodeProblem
from workflow_lib.types import Points, Polygons

from .dataset import paired_by_sample, sample_names
from .plots import make_plot
from .sample_pca import map_traces

CAPTION_STYLE = {"font-size": "13px", "color": "#555", "margin": "0 0 6px 0"}
NOTE_STYLE = {"color": "#6c757d"}

# One neutral colour when nothing is being distinguished.
PLAIN_COLOR = "#4a5568"
LINK_COLOR = "#999"


def points_from_table(rows, sample_col, x_dimension, dimension, opts):
    """
    `dimension` against `x_dimension`, per sample.

    Raises:
        NodeProblem: for an unset or repeated axis, a non-numeric axis, or no
            grain with both values
    """
    if not x_dimension:
        raise NodeProblem("Choose an x dimension.")
    if x_dimension == dimension:
        raise NodeProblem(f"'{dimension}' is already the x dimension; pick a "
                          f"different y dimension.")
    try:
        grouped = paired_by_sample(rows, sample_col, x_dimension, dimension,
                                   opts.get("samples"))
    except ValueError:
        raise NodeProblem(
            f"'{dimension}' is not numeric, so it cannot be a scatter axis.")
    if not grouped:
        raise NodeProblem(f"No paired '{x_dimension}' and '{dimension}' values.")

    total = sum(len(values[0]) for values in grouped.values())
    # Colour keyed to the sample's place in the spreadsheet, not its place in
    # the current selection — so a sample keeps its colour when the selection
    # changes and two outputs stay comparable.
    order = {name: index
             for index, name in enumerate(sample_names(rows, sample_col))}
    return Points(
        x_title=x_dimension, y_title=dimension,
        groups=[(sample, list(v[0]), list(v[1])) for sample, v in grouped.items()],
        note=(f"{total:,} grains across {len(grouped)} "
              f"sample{'s' if len(grouped) != 1 else ''}."),
        meta={"order": order}, name=dimension)


def draw_points(charts, layers, opts):
    """
    Plot one or more layers on shared axes.

    Args:
        layers: Points and Polygons. The first Points layer names the axes and
            the facets; every group, from every layer, is coloured by its name,
            so a hull drawn for a sample matches the sample's points.
        opts: layout ("overlay" or "facet"), color_by_sample, point_size, opacity
    """
    clouds = [layer for layer in layers if isinstance(layer, Points)]
    shapes = [layer for layer in layers if isinstance(layer, Polygons)]
    if not clouds and not shapes:
        raise NodeProblem("A scatterplot needs at least one set of points or one outline.")
    # Outlines alone (a watershed) are drawn as they are; the first layer then names the axes.
    base = clouds[0] if clouds else _OutlinesOnly(shapes[0])
    colors = _Colors(clouds, shapes, opts)
    if opts.get("layout") == "facet" and clouds:
        return _facets(charts, base, clouds, shapes, colors, opts)
    return _overlay(charts, base, clouds, shapes, colors, opts)


class _OutlinesOnly:
    """Stands in for the Points that name a plot's axes when there are none: the axes and title
    come from the first outline."""

    def __init__(self, outline):
        self.x_title, self.y_title = outline.x_title, outline.y_title
        self.title = outline.name or ""
        self.groups, self.meta, self.links, self.note = [], {}, [], ""


def _geographic_ratio(base, clouds, shapes):
    """
    For a plot of longitude against latitude, the y:x scale that makes a degree of latitude look as
    long as a degree of longitude does on the ground at the middle of the data's latitudes (1 / cos latitude), or
    None for any other plot. Without it a watershed is stretched sideways.
    """
    if not (str(base.x_title).startswith("Longitude") and str(base.y_title).startswith("Latitude")):
        return None
    lats = [y for layer in clouds for g in layer.groups for y in g[2]]
    lats += [v[1] for layer in shapes for _, vertices in layer.shapes for v in vertices]
    if not lats:
        return None
    middle = (min(lats) + max(lats)) / 2          # of the extent, not of the vertices' density
    return 1.0 / max(math.cos(math.radians(middle)), 0.05)


class _Colors:
    """The colour and shape each name is drawn with, the same in every layer."""

    def __init__(self, clouds, shapes, opts):
        self.plain = not opts.get("color_by_sample", True)
        self.order = dict(clouds[0].meta.get("order", {})) if clouds else {}
        for layer in clouds + shapes:
            names = ([g[0] for g in layer.groups] if isinstance(layer, Points)
                     else [n for n, _ in layer.shapes])
            for name in names:
                self.order.setdefault(name, len(self.order))

    def of(self, name):
        if self.plain:
            return PLAIN_COLOR, "circle"
        index = self.order.get(name, 0)
        return categorical_color(index), series_symbol(index)


def _traces(base, clouds, shapes, colors, opts, only=None):
    """Every trace for the chosen names (all of them when `only` is None)."""
    traces = []
    for layer in clouds:
        by_column = layer.meta.get("colors") or {}
        if only is None and layer.meta.get("labeled") and (
                "values" in by_column or "groups" in by_column):
            # Samples coloured by a column: drawn together so the colour scale
            # or the groups' legend covers them all.
            names = [g[0] for g in layer.groups]
            traces.extend(map_traces([g[1][0] for g in layer.groups],
                                     [g[2][0] for g in layer.groups], names, by_column))
            if layer.links:
                traces.insert(0, _links(layer.links))
            continue
        for name, xs, ys in layer.groups:
            if only is not None and name != only:
                continue
            color, symbol = colors.of(name)
            if layer.meta.get("labeled"):
                traces.append(marker_trace(xs, ys, name, color=color, labels=[name]))
                continue
            traces.append(scatter_trace(
                xs, ys, name, color=color, symbol=symbol,
                size=opts.get("point_size", 7),
                opacity=opts.get("opacity", 0.75),
                hover_x=layer.x_title, hover_y=layer.y_title))
        if only is None and layer.links:
            traces.insert(0, _links(layer.links))
    underlay = []                     # shaded fields go beneath the points, not over them
    for layer in shapes:
        for name, vertices in layer.shapes:
            # "Reference" means drawn dashed on every panel of a plot of points; with no points
            # the outline is the plot, and is drawn plainly.
            reference = name in layer.reference and bool(clouds)
            if only is not None and name != only and not reference:
                continue
            color = layer.colors.get(name) or colors.of(name)[0]
            path = list(vertices)
            if path and not layer.open:
                path.append(path[0])
            line = {"color": "#444" if reference else color, "width": 2}
            if reference:
                line["dash"] = "dash"
            trace = {
                "type": "scatter", "mode": "lines",
                "name": (name if reference or layer.fill or layer.bare
                         else f"{name} {'line' if layer.open else 'outline'}"),
                "x": [v[0] for v in path], "y": [v[1] for v in path],
                "line": line, "hoverinfo": "skip"}
            if layer.fill and not layer.open:
                trace.update({"fill": "toself", "fillcolor": _with_alpha(color, 0.2),
                              "hoveron": "fills", "hoverinfo": "name"})
                underlay.append(trace)
            else:
                traces.append(trace)
    return underlay + traces


def _with_alpha(color, alpha):
    """An rgba() colour from a "#rrggbb" one (any other form is left as it is, unshaded by alpha)."""
    text = str(color).lstrip("#")
    if len(text) == 6:
        try:
            r, g, b = (int(text[i:i + 2], 16) for i in (0, 2, 4))
            return f"rgba({r},{g},{b},{alpha})"
        except ValueError:
            pass
    return color


def _links(links):
    # A None breaks the line between segments; Plotly reads array entries as
    # values, so a non-numeric entry is simply a gap.
    xs, ys = [], []
    for x0, y0, x1, y1 in links:
        xs.extend([x0, x1, None])
        ys.extend([y0, y1, None])
    return {"type": "scatter", "mode": "lines", "x": xs, "y": ys,
            "name": "Nearest neighbor", "connectgaps": False, "hoverinfo": "skip",
            "line": {"color": LINK_COLOR, "width": 1, "dash": "dash"}}


def _axes(base, ratio=None, opts=None):
    # Measurements have no reason to reach zero; the default "tozero" would pad
    # a temperature axis down to 0 and waste most of the plot.
    axes = {
        "xaxis": {"title": {"text": base.x_title}, "rangemode": "normal"},
        "yaxis": {"title": {"text": base.y_title}, "rangemode": "normal"},
    }
    for key, option in (("xaxis", "x_scale"), ("yaxis", "y_scale")):
        if (opts or {}).get(option) == "log":
            axes[key]["type"] = "log"
    logged = any(a.get("type") == "log" for a in axes.values())
    if (opts or {}).get("equal_scale") and not logged and not ratio:
        ratio = 1.0                                 # a plan map: a unit looks as long either way
    if ratio and not logged:
        axes["yaxis"].update({"scaleanchor": "x", "scaleratio": ratio})
    if (opts or {}).get("y_reverse"):
        axes["yaxis"]["autorange"] = "reversed"     # depth, drawdown: the larger value lower down
    return axes


def _title(base):
    return base.title or f"{base.x_title} vs {base.y_title}"


def _filename(base):
    return f"{base.x_title}_{base.y_title}_scatter".replace(" ", "_")


def _overlay(charts, base, clouds, shapes, colors, opts):
    traces = _traces(base, clouds, shapes, colors, opts)
    wrapper = Div()
    notes = [layer.note for layer in (clouds or shapes) if layer.note]
    unshown = _off_log_axes(clouds, opts)
    if unshown:
        notes.append(f"{unshown:,} point{'s' if unshown != 1 else ''} with a zero or negative value "
                     "cannot be shown on a log axis.")
    if notes:
        wrapper.add(P(" ".join(notes), style=CAPTION_STYLE))
    wrapper.add(Div(make_plot(
        charts, traces, _title(base), base.x_title, base.y_title,
        height=520, show_legend=len(traces) > 1, filename=_filename(base),
        extra_layout=_axes(base, _geographic_ratio(base, clouds, shapes), opts)).element))

    # Past three series, colour alone cannot keep every pair apart — every
    # series touches every other on a scatter, so it is all pairs that have to
    # separate, not just neighbours. Marker shape carries identity too, which is
    # what makes more than three legible; say so rather than implying the
    # colours alone are doing the work.
    grains = [g for layer in clouds if not layer.meta.get("labeled")
              for g in layer.groups]
    if opts.get("color_by_sample", True) and len(grains) > SCATTER_CAP:
        wrapper.add(P(
            f"Beyond {SCATTER_CAP} samples the colours alone stop separating "
            f"reliably, so each sample also has its own marker shape. For many "
            f"samples, 'One plot per sample' reads more clearly.",
            style=NOTE_STYLE))
    return wrapper


def _off_log_axes(clouds, opts):
    """How many points a log axis cannot draw: those at or below zero on a log axis."""
    log_x, log_y = opts.get("x_scale") == "log", opts.get("y_scale") == "log"
    if not (log_x or log_y):
        return 0
    return sum(1 for layer in clouds for _, xs, ys in layer.groups for x, y in zip(xs, ys)
               if (log_x and x <= 0) or (log_y and y <= 0))


def _facets(charts, base, clouds, shapes, colors, opts):
    """
    One panel per sample, on shared axes.

    Shared ranges are the point: panels that each auto-scale would show every
    sample filling its own frame and hide the differences between them.
    """
    names = [g[0] for g in base.groups]
    all_x = [v for layer in clouds for g in layer.groups for v in g[1]]
    all_y = [v for layer in clouds for g in layer.groups for v in g[2]]
    axes = _axes(base, _geographic_ratio(base, clouds, shapes), opts)
    y_range = _padded(all_y, log=opts.get("y_scale") == "log")
    limits = {"xaxis": {**axes["xaxis"], "range": _padded(all_x, log=opts.get("x_scale") == "log")},
              "yaxis": {**axes["yaxis"], "range": y_range[::-1] if opts.get("y_reverse") else y_range}}
    limits["yaxis"].pop("autorange", None)          # an explicit range, already turned round if need be

    wrapper = Div(P(f"{len(names)} samples on shared axes.", style=CAPTION_STYLE))
    for name in names:
        traces = _traces(base, clouds, shapes, colors, opts, only=name)
        wrapper.add(Div(make_plot(
            charts, traces, f"{name} — {base.x_title} vs {base.y_title}",
            base.x_title, base.y_title, height=380, show_legend=False,
            filename=f"{name}_{_filename(base)}", extra_layout=limits).element))
        count = len(dict((g[0], g[1]) for g in base.groups)[name])
        wrapper.add(P(f"n = {count:,}",
                      style={**CAPTION_STYLE, "margin": "0 0 14px 0"}))
    return wrapper


def _padded(values, fraction=0.04, log=False):
    """A range with a little air, so points never sit on the frame; in powers of ten on a log axis
    (where a value that is zero or below cannot be drawn and is left out)."""
    if log:
        values = [math.log10(v) for v in values if v > 0] or [0.0]
    low, high = min(values), max(values)
    pad = (high - low) * fraction or (abs(low) * 0.04 or 1.0)
    return [low - pad, high + pad]

scripts/dashboard/table_ops.py:
"""
Cleaning and reshaping a table: filter its grains, add a transformed column, add a
ratio. Each returns a new table and leaves the one it was given alone; what
happened is returned alongside, so the step can say what it did.
"""
import math
from dataclasses import dataclass, field

import numpy as np

from sed_stats import dates as dt
from sed_stats import isotopes as iso
from workflow_lib import NodeProblem

# How a column can be transformed: key -> (label for the new column's name, function,
# what the function cannot take, as a phrase for the report).
TRANSFORMS = {
    "log10": ("log10", lambda v: math.log10(v), lambda v: v > 0, "not above zero"),
    "ln": ("ln", lambda v: math.log(v), lambda v: v > 0, "not above zero"),
    "sqrt": ("sqrt", lambda v: math.sqrt(v), lambda v: v >= 0, "negative"),
    "reciprocal": ("1/", lambda v: 1.0 / v, lambda v: v != 0, "zero"),
}
TRANSFORM_LABELS = {
    "log10": "log₁₀", "ln": "natural log", "sqrt": "square root", "reciprocal": "reciprocal (1/x)",
    "zscore": "z-score (over all grains)", "zscore_sample": "z-score within each sample",
}
FILTER_HOW = {
    "samples": "Only choose samples",
    "range": "Keep grains whose value is within a range",
    "values": "Keep grains whose value is one of these",
    "present": "Drop grains that have no value",
}


def number_of(value):
    """A finite float from a cell, or None for blank, text, NaN and infinity."""
    if value is None or isinstance(value, bool):
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def _sample_of(row, sample_col):
    return str(row.get(sample_col, "") or "").strip()


def _blank(value):
    return value is None or str(value).strip() == ""


# --------------------------------------------------------------------- filtering

@dataclass
class FilterResult:
    rows: list
    before: dict = field(default_factory=dict)       # sample -> grains in
    after: dict = field(default_factory=dict)        # sample -> grains kept
    summary: str = ""


def filter_rows(rows, sample_col, samples=None, how="samples", column=None,
                minimum=None, maximum=None, values=None):
    """
    Keep some of the grains.

    Args:
        samples: only these samples (all when None)
        how: "samples" (nothing more), "range" (`column` between `minimum` and
            `maximum`, either may be left out, both inclusive), "values" (`column`
            is one of the comma-separated `values`) or "present" (`column` has a
            value)

    Raises:
        NodeProblem: for a filter that is missing a piece, or leaves no grains
    """
    if how not in FILTER_HOW:
        raise NodeProblem(f"Unknown filter '{how}'.")
    if how != "samples" and not column:
        raise NodeProblem("Choose the column to filter on.")
    if how == "range" and minimum is None and maximum is None:
        raise NodeProblem("Give a minimum, a maximum, or both.")
    wanted = None
    if how == "values":
        wanted = {v.strip() for v in str(values or "").split(",") if v.strip()}
        if not wanted:
            raise NodeProblem("List the values to keep, separated by commas.")
    chosen = set(samples) if samples is not None else None

    result = FilterResult([])
    for row in rows:
        sample = _sample_of(row, sample_col)
        if chosen is not None and sample not in chosen:
            continue
        result.before[sample] = result.before.get(sample, 0) + 1
        if not _passes(row.get(column) if column else None, how, minimum, maximum, wanted):
            continue
        result.after[sample] = result.after.get(sample, 0) + 1
        result.rows.append(dict(row))
    kept, seen = len(result.rows), sum(result.before.values())
    if not kept:
        raise NodeProblem("No grains are left after this filter.")
    result.summary = (f"Kept {kept:,} of {seen:,} grains"
                      + (f" ({_describe(how, column, minimum, maximum, wanted)})"
                         if how != "samples" else "") + ".")
    return result


def _passes(value, how, minimum, maximum, wanted):
    if how == "samples":
        return True
    if how == "present":
        return not _blank(value)
    if how == "values":
        return str(value).strip() in wanted
    number = number_of(value)
    if number is None:
        return False
    return ((minimum is None or number >= minimum)
            and (maximum is None or number <= maximum))


def _describe(how, column, minimum, maximum, wanted):
    if how == "present":
        return f"{column} has a value"
    if how == "values":
        return f"{column} is {' or '.join(sorted(wanted))}"
    low = f"{minimum:g} ≤ " if minimum is not None else ""
    high = f" ≤ {maximum:g}" if maximum is not None else ""
    return f"{low}{column}{high}"


# ------------------------------------------------------------------ new columns

@dataclass
class ColumnResult:
    rows: list
    name: str
    made: int = 0               # grains given a value
    blank: int = 0              # grains left blank, and why (see `reason`)
    reason: str = ""
    replaced: bool = False      # an existing column of that name was overwritten
    summary: str = ""


def _finish(rows, name, values, reason):
    existing = bool(rows) and name in rows[0]
    out = []
    for row, value in zip(rows, values):
        new = dict(row)
        new[name] = "" if value is None else value
        out.append(new)
    made = sum(1 for v in values if v is not None)
    result = ColumnResult(out, name, made, len(values) - made, reason, existing)
    parts = [f"Added '{name}': {made:,} value{'s' if made != 1 else ''}"]
    if result.blank:
        parts.append(f"{result.blank:,} left blank ({reason})")
    summary = "; ".join(parts) + "."
    if existing:
        summary += f" This replaced the column that was already called '{name}'."
    result.summary = summary
    if not made:
        raise NodeProblem(f"Every value came out blank ({reason}), so there is nothing "
                          "to add.")
    return result


def transform_column(rows, sample_col, column, function, name=None):
    """
    A copy of the table with `column` transformed into a new column.

    Values the function cannot take (the log of zero) are left blank rather than
    guessed. Uncertainty columns are not transformed with it, and a new name no
    longer matches the old column's, so the new column is treated as having none.

    Raises:
        NodeProblem: for an unknown function or no usable values
    """
    if function not in TRANSFORM_LABELS:
        raise NodeProblem(f"Unknown transformation '{function}'.")
    if not column:
        raise NodeProblem("Choose the column to transform.")
    numbers = [number_of(row.get(column)) for row in rows]
    if function in TRANSFORMS:
        label, apply, valid, reason = TRANSFORMS[function]
        values = [apply(v) if v is not None and valid(v) else None for v in numbers]
        blank_reason = f"values that are {reason} or missing"
        default = f"{label}{column}" if label.endswith("/") else f"{label}({column})"
    else:
        values = _standardised(rows, sample_col, numbers, within=function == "zscore_sample")
        blank_reason = "missing, or a sample with no spread"
        default = f"z({column})"
    return _finish(rows, (name or "").strip() or default, values, blank_reason)


def _standardised(rows, sample_col, numbers, within):
    groups = {}
    for index, (row, number) in enumerate(zip(rows, numbers)):
        if number is not None:
            key = _sample_of(row, sample_col) if within else ""
            groups.setdefault(key, []).append(index)
    out = [None] * len(rows)
    for indexes in groups.values():
        data = np.array([numbers[i] for i in indexes])
        spread = data.std(ddof=1) if len(data) > 1 else 0.0
        if spread <= 0:
            continue
        for i, z in zip(indexes, (data - data.mean()) / spread):
            out[i] = float(z)
    return out


def ratio_column(rows, numerator, denominator, name=None, factor=1.0):
    """
    A copy of the table with `factor * numerator / denominator` as a new column
    (blank where either is missing or the denominator is zero). The factor turns a
    ratio of weights into one of atoms, or a ratio into per mil.

    Raises:
        NodeProblem: for the same column twice, or no usable pairs
    """
    if not numerator or not denominator:
        raise NodeProblem("Choose both columns.")
    if numerator == denominator:
        raise NodeProblem("The ratio of a column to itself is always 1; choose two "
                          "different columns.")
    values = []
    for row in rows:
        top, bottom = number_of(row.get(numerator)), number_of(row.get(denominator))
        values.append(factor * top / bottom
                      if top is not None and bottom not in (None, 0) else None)
    return _finish(rows, (name or "").strip() or f"{numerator}/{denominator}", values,
                   "either value missing, or the denominator zero")


# --------------------------------------------------------------------- isotopes

def _derived(rows, name, columns, function, reason):
    """
    A new column from `function(*numbers)` of the named columns, row by row. A row
    with any of them missing, or for which the function raises ValueError (outside
    its domain), is left blank.
    """
    values = []
    for row in rows:
        numbers = [number_of(row.get(c)) for c in columns]
        if any(n is None for n in numbers):
            values.append(None)
            continue
        try:
            values.append(function(*numbers))
        except (ValueError, ZeroDivisionError):
            values.append(None)
    return _finish(rows, name, values, reason)


def _need(**columns):
    for label, column in columns.items():
        if not column:
            raise NodeProblem(f"Choose the {label.replace('_', ' ')} column.")


def convert_scale(rows, column, conversion, name=None):
    """
    Delta-18O between the VPDB and VSMOW scales, by Coplen et al. (1983) or the IUPAC
    values; `conversion` is "vpdb_to_vsmow" or "vsmow_to_vpdb", optionally suffixed
    ":iupac".
    """
    _need(**{"delta": column})
    direction, _, which = str(conversion).partition(":")
    which = which or "coplen"
    if direction not in ("vpdb_to_vsmow", "vsmow_to_vpdb") or which not in iso.OXYGEN_SCALE_CONVERSIONS:
        raise NodeProblem(f"Unknown conversion '{conversion}'.")
    convert = iso.vpdb_to_vsmow if direction == "vpdb_to_vsmow" else iso.vsmow_to_vpdb
    target = "VSMOW" if direction == "vpdb_to_vsmow" else "VPDB"
    return _derived(rows, (name or "").strip() or f"{column} ({target})", [column],
                    lambda d: convert(d, which), "value missing")


def difference_column(rows, first, second, form="difference", factor=1.0, name=None):
    """
    first - factor * second ("difference": d-excess with factor 8, or an
    enrichment), or 1000 ln(alpha) of the first against the second ("ln_alpha").
    """
    _need(first=first, second=second)
    if first == second:
        raise NodeProblem("Choose two different columns.")
    if form == "ln_alpha":
        return _derived(rows, (name or "").strip() or f"1000 ln α ({first}/{second})",
                        [first, second], iso.thousand_ln_alpha,
                        "value missing, or a delta at or below -1000")
    if form != "difference":
        raise NodeProblem(f"Unknown form '{form}'.")
    default = f"{first} - {factor:g}*{second}" if factor != 1 else f"{first} - {second}"
    return _derived(rows, (name or "").strip() or default, [first, second],
                    lambda a, b: a - factor * b, "value missing")


def lipid_column(rows, d13c, cn, name=None, intercept=iso.LIPID_INTERCEPT, slope=iso.LIPID_SLOPE):
    """Post et al. (2007) lipid-normalised delta-13C from delta-13C and atomic C:N."""
    _need(delta_13C=d13c, C_N=cn)
    return _derived(rows, (name or "").strip() or f"{d13c} (lipid-normalised)", [d13c, cn],
                    lambda d, c: d + intercept + slope * c, "value missing")


def trophic_column(rows, d15n, baseline, position=2.0, enrichment=iso.DEFAULT_ENRICHMENT,
                   name=None):
    """Trophic position (Post 2002) from delta-15N, against a baseline delta-15N."""
    _need(delta_15N=d15n)
    if enrichment <= 0:
        raise NodeProblem("The enrichment per trophic level must be above zero.")
    if baseline is None:
        raise NodeProblem("Give the baseline delta-15N.")
    return _derived(rows, (name or "").strip() or "Trophic position", [d15n],
                    lambda d: iso.trophic_position(d, baseline, position, enrichment),
                    "value missing")


CARBONATE_EQUATIONS = {
    "shackleton": "Shackleton (1974) / O'Neil et al. (1969)",
    "kim_oneil": "Kim & O'Neil (1997)",
    "kim_oneil_recalculated": "Kim & O'Neil (1997), recalculated",
    "custom": "Your own: T = a + b·x + c·x²",
}


def temperature_column(rows, calcite, equation="shackleton", calcite_scale="vpdb",
                       water=0.0, water_column=None, coefficients=(0.0, 0.0, 0.0), name=None):
    """
    Carbonate-water temperature (degrees C) from delta-18O of the calcite and of the
    water it grew in (a constant, or a column), both on the scales stated: calcite on
    `calcite_scale` ("vpdb" or "vsmow"), water on VSMOW.
    """
    _need(calcite=calcite)
    if equation not in CARBONATE_EQUATIONS:
        raise NodeProblem(f"Unknown equation '{equation}'.")
    columns = [calcite] + ([water_column] if water_column else [])

    def vpdb(d):
        return d if calcite_scale == "vpdb" else iso.vsmow_to_vpdb(d)

    def vsmow(d):
        return iso.vpdb_to_vsmow(d) if calcite_scale == "vpdb" else d

    def temperature(d, w=None):
        w = water if w is None else w
        if equation == "shackleton":
            return iso.temperature_shackleton(vpdb(d), w)
        if equation == "custom":
            return iso.temperature_polynomial(vpdb(d), w, *coefficients)
        constants = iso.KIM_ONEIL if equation == "kim_oneil" else iso.KIM_ONEIL_RECALCULATED
        return iso.temperature_kim_oneil(vsmow(d), w, constants)

    return _derived(rows, (name or "").strip() or "Temperature (°C)", columns, temperature,
                    "value missing, or outside the equation's range")


# ------------------------------------------------------------------------- dates

DATE_PARTS = {
    "year": "Year",
    "month": "Month number",
    "month_name": "Month name",
    "year_month": "Year and month (2021-01)",
    "water_year": "Water year",
    "day_of_water_year": "Day of the water year",
    "day_of_year": "Day of the year (1–366; often called the “Julian day”)",
    "decimal_year": "Decimal year (2021.54)",
    "julian_date": "Julian date, JD (days from noon 1 Jan 4713 BC: 2459215.5)",
    "modified_julian_date": "Modified Julian date, MJD (JD − 2400000.5: 59215.0)",
    "julian_day_number": "Julian day number (whole days: 2459216)",
    "season": "Season (Winter, Spring, Summer, Autumn)",
    "two_seasons": "Two seasons, by the months you give",
}
_DEFAULT_NAMES = {
    "year": "year", "month": "month", "month_name": "month_name", "year_month": "year_month",
    "water_year": "water_year", "day_of_water_year": "day_of_water_year",
    "day_of_year": "day_of_year", "decimal_year": "decimal_year", "season": "season",
    "julian_date": "julian_date", "modified_julian_date": "mjd", "julian_day_number": "julian_day_number",
    "two_seasons": "season",
}


def date_part_column(rows, column, part, name=None, day_first=False, water_year_start=10,
                     hemisphere="north", season_months="", first_name="First season",
                     second_name="Second season"):
    """
    A copy of the table with one part of each row's date as a new column.

    Rows whose date cannot be read are left blank, and the first few such values are named in
    the result so a format that is not understood is easy to spot.

    Raises:
        NodeProblem: for no column or part, a bad month list, or no readable date at all
    """
    if not column:
        raise NodeProblem("Choose the date column.")
    if part not in DATE_PARTS:
        raise NodeProblem(f"Unknown date part '{part}'.")
    months = None
    if part == "two_seasons":
        try:
            months = dt.parse_months(season_months)
        except ValueError as error:
            raise NodeProblem(str(error)) from None
        if not first_name.strip() or not second_name.strip() or first_name == second_name:
            raise NodeProblem("Give the two seasons different names.")
    start = int(water_year_start or 10)
    if not 1 <= start <= 12:
        raise NodeProblem("The water year must start in a month from 1 to 12.")

    def make(when):
        if part == "year":
            return when.year
        if part == "month":
            return when.month
        if part == "month_name":
            return dt.MONTH_NAMES[when.month - 1]
        if part == "year_month":
            return f"{when.year}-{when.month:02d}"
        if part == "water_year":
            return dt.water_year(when, start)
        if part == "day_of_water_year":
            return dt.day_of_water_year(when, start)
        if part == "day_of_year":
            return dt.day_of_year(when)
        if part == "decimal_year":
            return round(dt.decimal_year(when), 4)
        if part == "julian_date":
            return round(dt.julian_date(when), 6)
        if part == "modified_julian_date":
            return round(dt.modified_julian_date(when), 6)
        if part == "julian_day_number":
            return dt.julian_day_number(when)
        if part == "season":
            return dt.season(when, hemisphere)
        return dt.two_seasons(when, months, first_name.strip(), second_name.strip())

    values, bad = [], []
    for row in rows:
        raw = row.get(column)
        when = dt.parse_date(raw, day_first)
        if when is None:
            values.append(None)
            if not _blank(raw) and len(bad) < 3 and str(raw) not in bad:
                bad.append(str(raw))
        else:
            values.append(make(when))
    reason = "no readable date" + (f" (for example '{bad[0]}')" if bad else "")
    result = _finish(rows, (name or "").strip() or _DEFAULT_NAMES[part], values, reason)
    if bad:
        result.summary += (" Not read as dates: " + ", ".join(f"'{b}'" for b in bad)
                           + ("; the order of day and month can be switched." if "/" in "".join(bad) else "."))
    return result


def regroup_samples(rows, sample_col, column, mode="replace", separator=" · "):
    """
    A copy of the table whose sample names come from another column — a season, a year, a
    site — so that every tool that works by sample now works by that grouping. The old names
    are kept in a column of their own.

    Args:
        mode: "replace" (the column's value is the sample) or "append" (old name, separator, value)

    Returns:
        ColumnResult whose rows carry the new names, and whose `summary` says how many
        samples there now are
    """
    if not column:
        raise NodeProblem("Choose the column to group by.")
    if column == sample_col:
        raise NodeProblem("That is already the sample column.")
    if mode not in ("replace", "append"):
        raise NodeProblem(f"Unknown mode '{mode}'.")
    kept = f"{sample_col} (original)"
    out, blanks = [], 0
    for row in rows:
        value = str(row.get(column, "") if row.get(column) is not None else "").strip()
        if value.endswith(".0") and value[:-2].lstrip("-").isdigit():
            value = value[:-2]                     # 2021.0 from a column read as numbers
        if not value:
            value, blanks = "(blank)", blanks + 1
        old = str(row.get(sample_col, "") if row.get(sample_col) is not None else "").strip()
        new = {}
        for key, cell in row.items():
            new[key] = (value if mode == "replace" else f"{old}{separator}{value}") if key == sample_col else cell
        new[kept] = old
        out.append(new)
    names = list(dict.fromkeys(r[sample_col] for r in out))
    summary = (f"{len(rows):,} rows now fall in {len(names)} sample{'s' if len(names) != 1 else ''}: "
               + ", ".join(names[:8]) + ("…" if len(names) > 8 else "") + "."
               + (f" {blanks:,} had no value in '{column}' and are called '(blank)'." if blanks else ""))
    result = ColumnResult(out, sample_col, made=len(out), blank=blanks, summary=summary)
    return result


@dataclass
class SummaryResult:
    rows: list
    columns: list
    summary: str = ""


def sample_summary(rows, sample_col, columns, weight_column=None):
    """
    One row per sample: how many values, and for each column the mean, standard deviation and
    standard error of the mean; with a weight column also the weighted mean and its standard
    error, where the weights are amounts (precipitation depth, discharge), not precisions —
    so a large storm counts for more, which is how an amount-weighted mean of precipitation
    isotopes is defined.

    Raises:
        NodeProblem: for no columns, or no sample with a number in any of them
    """
    if not columns:
        raise NodeProblem("Choose at least one column.")
    out, order = [], []
    for row in rows:
        sample = _sample_of(row, sample_col)
        if sample and sample not in order:
            order.append(sample)
    for sample in order:
        selected = [r for r in rows if _sample_of(r, sample_col) == sample]
        line = {sample_col: sample, "n": len(selected)}
        for column in columns:
            pairs = [(number_of(r.get(column)), number_of(r.get(weight_column)) if weight_column else 1.0)
                     for r in selected]
            values = np.array([v for v, w in pairs if v is not None])
            line[f"{column} mean"] = float(values.mean()) if len(values) else ""
            line[f"{column} SD"] = float(values.std(ddof=1)) if len(values) > 1 else ""
            line[f"{column} SE"] = float(values.std(ddof=1) / math.sqrt(len(values))) if len(values) > 1 else ""
            line[f"{column} n"] = len(values)
            if weight_column:
                both = [(v, w) for v, w in pairs if v is not None and w is not None and w >= 0]
                if len(both) > 1 and sum(w for _, w in both) > 0:
                    mean, se = iso_weighted(both)
                    line[f"{column} weighted mean"] = mean
                    line[f"{column} weighted SE"] = se if math.isfinite(se) else ""
                else:
                    line[f"{column} weighted mean"] = line[f"{column} weighted SE"] = ""
        out.append(line)
    if not any(isinstance(v, float) for line in out for k, v in line.items() if k.endswith(" mean")):
        raise NodeProblem("None of the chosen columns holds a number in any sample.")
    titles = list(out[0].keys())
    weighted = f", weighted by {weight_column}" if weight_column else ""
    return SummaryResult(out, titles, f"{len(out)} sample{'s' if len(out) != 1 else ''}, "
                                      f"{len(columns)} column{'s' if len(columns) != 1 else ''}{weighted}.")


def iso_weighted(pairs):
    """(weighted mean, standard error) of [(value, weight)], by Kirchner & Allen's amount-weighted formulas."""
    from sed_stats.emsa import weighted_mean_and_se
    return weighted_mean_and_se([v for v, _ in pairs], [w for _, w in pairs])

scripts/dashboard/ternary_plot.py:
"""
The Ternary tool's output: three components of a whole, one point per grain.

The three apex dimensions are chosen in the wizard rather than taken from the
dimension checklist, because on a triangle the order matters — which component
sits at the top is part of the diagram's meaning, and a checklist cannot say.
"""
from antioch.elements import Div, P

from plot_lib import (
    categorical_color, series_symbol, ternary_layout, ternary_trace,
)
from sed_stats import ternary

from .config import TERNARY_TOTAL
from .dataset import sample_names
from .plots import make_plot
from .tables import result_table

CAPTION_STYLE = {"font-size": "13px", "color": "#555", "margin": "0 0 6px 0"}
NOTE_STYLE = {"color": "#6c757d"}

PLAIN_COLOR = "#4a5568"
CENTROID_COLOR = "#1a1a1a"


def build_ternary(charts, rows, sample_col, dimension, opts):
    """
    `dimension` is ignored — the three apexes come from the options panel.

    The tool runs with use_dimensions off, so there is one output rather than
    a tab per dimension.
    """
    apexes = [opts.get("apex_a"), opts.get("apex_b"), opts.get("apex_c")]
    if not all(apexes):
        return P("Choose all three apex dimensions.", style=NOTE_STYLE)
    if len(set(apexes)) < 3:
        return P("The three apexes must be different dimensions.",
                 style=NOTE_STYLE)

    grouped = _components_by_sample(rows, sample_col, apexes,
                                    opts.get("samples"))
    if not grouped:
        return P("No grains have a value for all three apex dimensions.",
                 style=NOTE_STYLE)

    order = {name: index
             for index, name in enumerate(sample_names(rows, sample_col))}
    closed = {sample: ternary.close(*parts, total=TERNARY_TOTAL)
              for sample, parts in grouped.items()}
    closed = {sample: data for sample, data in closed.items() if len(data)}
    if not closed:
        return P("Every grain had a zero or negative total across the three "
                 "components, so none can be placed on the triangle.",
                 style=NOTE_STYLE)

    traces = []
    for sample, data in closed.items():
        index = order.get(sample, 0)
        color, symbol = ((categorical_color(index), series_symbol(index))
                         if opts.get("color_by_sample", True)
                         else (PLAIN_COLOR, "circle"))
        traces.append(ternary_trace(
            data.a, data.b, data.c, sample,
            color=color, symbol=symbol,
            size=opts.get("point_size", 7),
            apex_names=apexes,
        ))

    if opts.get("show_centroids"):
        traces.extend(_centroid_traces(closed, apexes))

    title = f"{apexes[0]} – {apexes[1]} – {apexes[2]}"
    wrapper = Div(
        _caption(closed, apexes),
        Div(make_plot(
            charts, traces, title, apexes[1], apexes[2],
            height=560, show_legend=len(traces) > 1,
            filename=f"{'_'.join(apexes)}_ternary",
            extra_layout=ternary_layout(apexes, total=TERNARY_TOTAL),
        ).element),
    )
    if opts.get("show_centroids"):
        wrapper.add(_centroid_table(closed, apexes))
    return wrapper


def _components_by_sample(rows, sample_col, apexes, only_samples):
    """
    The three apex values per grain, grouped by sample.

    A grain missing any one component has no position on the triangle, so it
    is left out rather than treated as a zero — absent and zero mean different
    things in a composition.
    """
    grouped = {}
    for row in rows:
        sample = str(row.get(sample_col, "") or "").strip()
        if not sample:
            continue
        if only_samples is not None and sample not in only_samples:
            continue
        values = []
        for apex in apexes:
            raw = row.get(apex, "")
            if raw in ("", None):
                values = None
                break
            try:
                values.append(float(raw))
            except (TypeError, ValueError):
                values = None
                break
        if values is None:
            continue
        entry = grouped.setdefault(sample, ([], [], []))
        for slot, value in zip(entry, values):
            slot.append(value)
    return grouped


def _caption(closed, apexes):
    """State the plot's size, and anything that had to be done to the data."""
    plotted = sum(len(data) for data in closed.values())
    dropped = sum(data.dropped_total for data in closed.values())

    text = (f"{plotted:,} grains across {len(closed)} "
            f"sample{'s' if len(closed) != 1 else ''}, "
            f"{apexes[0]} at the top with {apexes[1]} and {apexes[2]} "
            f"along the base.")

    if any(data.needed_closure for data in closed.values()):
        lows = [data.closure_range[0] for data in closed.values()]
        highs = [data.closure_range[1] for data in closed.values()]
        text += (f" Raw totals ran {min(lows):.3g}–{max(highs):.3g}, so each "
                 f"grain was scaled to {TERNARY_TOTAL:g}.")
    else:
        text += f" Totals were already {TERNARY_TOTAL:g}."

    caption = Div(P(text, style=CAPTION_STYLE))
    if dropped:
        caption.add(P(f"{dropped:,} grain{'s' if dropped != 1 else ''} left out "
                      f"for a zero or negative total.", style=NOTE_STYLE))
    return caption


def _centroid_traces(closed, apexes):
    """A ringed marker per sample at its mean composition."""
    traces = []
    for sample, data in closed.items():
        a, b, c = ternary.centroid(data)
        trace = ternary_trace([a], [b], [c], f"{sample} mean",
                              color=CENTROID_COLOR, symbol="star", size=14,
                              opacity=1.0, apex_names=apexes)
        trace["marker"]["line"] = {"width": 1.4, "color": "#ffffff"}
        trace["showlegend"] = False
        traces.append(trace)
    return traces


def _centroid_table(closed, apexes):
    body = []
    for sample, data in closed.items():
        a, b, c = ternary.centroid(data)
        body.append([sample, f"{a:.1f}", f"{b:.1f}", f"{c:.1f}", f"{len(data):,}"])

    return Div(
        P("Mean composition per sample",
          style={**CAPTION_STYLE, "margin": "16px 0 6px 0"}),
        result_table(["Sample", *apexes, "n"], body),
    )

scripts/dashboard/tool_runner.py:
"""
Running a tool: its chain of blocks, on a table, to one output.

The tool's steps are laid out as a throwaway workflow and run by the same engine
the Workflow tab uses, so a tool and the blocks it is made of cannot disagree.
Whatever the steps draw is gathered into a single output, and a tool that adds
columns to the spreadsheet hands those back.
"""
from dataclasses import dataclass

from antioch.elements import Div

from workflow_lib import DATA, Workflow, WorkflowEngine
from workflow_lib.workflow import source_ref
from workflow_lib.engine import OK
from workflow_lib.tools import TABLE_INPUT, instantiate, sheet_step

from . import nodes
from .nodes import StepOutput


class ToolFailure(Exception):
    """A step of the tool could not run; the message says which and why."""


@dataclass
class ToolResult:
    output: StepOutput
    sheet_rows: list = None     # the table to write back to the spreadsheet, if any


def run_tool(tool, opts, rows):
    """
    Run `tool` with the dialog's `opts` on `rows`.

    Raises:
        ToolFailure: if a step fails; later steps that needed it are not run
    """
    planned = instantiate(tool, opts)
    workflow = Workflow()
    real = {}
    def actual(source):
        """The workflow's own name for a source the tool wired by its local one."""
        if source == TABLE_INPUT:
            return DATA
        local, _, output = source.partition(".")
        return source_ref(real[local], output)

    for step in planned:
        inputs = {port: [actual(s) for s in sources] for port, sources in step.inputs.items()}
        real[step.id] = workflow.add(step.node, step.options, inputs).id
    engine = WorkflowEngine(workflow, lambda: rows, nodes.specs(),
                            nodes.compute, nodes.render)

    outputs = []
    for result in engine.run_all():
        if result.status != OK:
            label = nodes.NODES[workflow.get(result.step_id).tool].label
            raise ToolFailure(f"{label}: {result.message}")
        if isinstance(result.report, StepOutput):
            outputs.append(result.report)

    sheet_rows = None
    target = sheet_step(tool, opts)
    if target is not None:
        sheet_rows = engine.batch_for(real[target])[0]
    return ToolResult(_combine(outputs, opts.get("title") or tool.label), sheet_rows)


def _combine(outputs, title):
    """One output from what the steps drew: as it is for one, stacked for several."""
    if not outputs:
        return StepOutput(title, Div(), [], None)
    if len(outputs) == 1:
        only = outputs[0]
        return StepOutput(title, only.body, only.charts, only.tabview)
    charts = [chart for out in outputs for chart in out.charts]
    return StepOutput(title, Div(*[out.body for out in outputs]), charts, None)

scripts/dashboard/toolboxes.py:
"""
Toolboxes: tools grouped for the menus, and what a tool needs to be a dialog.

`ToolRegistry` holds every tool — the built-in ones and any the user has saved —
and lists them by toolbox. `ToolNode` dresses a tool as a block for the dialog:
the dialog is built from a node's ports and option fields, and a tool's fields are
its parameters, each taken from the option of the block it controls, so a tool's
dialog says exactly what that block's own dialog would.
"""
from dataclasses import replace

from workflow_lib import NodeSpec, Port, TABLE, ToolError
from workflow_lib.tools import condition_holds, instantiate, resolved_values

from .builtin_tools import BUILTIN_TOOLS, HIDDEN_TOOLS, MENU_ORDER, TOOLBOX_ORDER
from .nodes import (
    CHECKBOX, DIMENSION, DIMENSIONS, Field, NODES, NUMBER, OPTIONS_PAGE,
    SAMPLE, SAMPLES, SELECT, TEXT,
)

FIELD_KINDS = {"select": SELECT, "checkbox": CHECKBOX, "number": NUMBER, "text": TEXT,
               "dimensions": DIMENSIONS, "dimension": DIMENSION,
               "samples": SAMPLES, "sample": SAMPLE}


def _when(condition):
    return (lambda opts: condition_holds(condition, opts)) if condition else None


def build_field(tool, param):
    """The dialog Field for one parameter of `tool`."""
    if param.source:
        step_id, _, option = param.source.partition(".")
        node = NODES[tool.step(step_id).node]
        base = next((f for f in node.fields if f.key == option), None)
        if base is None:
            raise ToolError(f"Block '{node.key}' has no option '{option}' "
                            f"(parameter '{param.key}' of '{tool.key}').")
        # The block's own condition is written in terms of its own option
        # names, so it only carries over while the parameter keeps the name.
        keep_when = base.when if param.key == option else None
        return replace(
            base, key=param.key, label=param.label or base.label,
            hint=param.hint or base.hint, page=param.page or base.page,
            default=param.default if param.default is not None else base.default,
            # `when={}` says "always shown"; leaving it out keeps the block's own.
            when=_when(param.when) if param.when is not None else keep_when)
    spec = param.field or {}
    kind = FIELD_KINDS.get(spec.get("kind", "select"))
    if kind is None:
        raise ToolError(f"Parameter '{param.key}' has an unknown kind '{spec.get('kind')}'.")
    return Field(param.key, param.label or spec.get("label", param.key), kind,
                 hint=param.hint or spec.get("hint", ""), choices=spec.get("choices"),
                 default=spec.get("default", param.default),
                 numeric_only=spec.get("numeric_only", False),
                 signed=spec.get("signed", False),
                 unchecked=spec.get("unchecked", False),
                 page=param.page or spec.get("page", OPTIONS_PAGE),
                 when=_when(param.when))


class ToolNode:
    """A tool, shaped like a block so the same dialog can collect its parameters."""

    is_tool = True

    def __init__(self, tool):
        self.tool = tool
        self.key = tool.key
        self.label = tool.label
        self.description = tool.description
        self.fields = [build_field(tool, p) for p in tool.params]
        # A tool is run on a table; the dialog asks which when it is added to a workflow.
        self.spec = NodeSpec(tool.key, tool.label, tool.toolbox,
                             (Port("table", (TABLE,), "Table"),) if tool.needs_table else (), None)

    def validate(self, opts, context):
        """
        The first problem any block in the chain would raise for these choices,
        then the tool's own check.
        """
        for planned in instantiate(self.tool, opts):
            node = NODES[planned.node]
            if node.validate:
                try:
                    problem = node.validate(planned.options, context)
                except KeyError:
                    continue            # an option no parameter supplies yet
                if problem:
                    return problem
        check = TOOL_CHECKS.get(self.tool.key)
        return check(resolved_values(self.tool, opts)) if check else None


def _at_least(count, what):
    def check(values):
        chosen = len(values.get("samples") or [])
        if chosen < count:
            return f"{what} needs at least {count} samples; {chosen} selected."
        return None
    return check


def _sink_among_samples(values):
    samples = values.get("samples") or []
    if values.get("sink") not in samples:
        return f"The sink '{values.get('sink')}' is not among the selected samples."
    if len(samples) < 3:
        return "Select the sink plus at least two source samples."
    return None


# What a tool's blocks cannot check alone: how many samples it needs of the ones chosen.
TOOL_CHECKS = {
    "matrix": _at_least(2, "A comparison"),
    "mds": _at_least(3, "MDS"),
    "mixture": _sink_among_samples,
    "unmix_pc1": _sink_among_samples,
}


class ToolRegistry:
    """Every tool available, by key, and the toolboxes they are listed under."""

    def __init__(self, tools=()):
        self.tools = {}
        self._nodes = {}
        self._builtin = set()
        self.on_change = None       # called after tools are added or removed
        for tool in tools:
            self.add(tool)
        self._builtin = set(self.tools)

    def add(self, tool):
        build = ToolNode(tool)      # fails now, not at the first click, if it is unusable
        self.tools[tool.key] = tool
        self._nodes[tool.key] = build
        self._changed()
        return build

    def remove(self, key):
        """Remove one of the user's tools; the built-in ones stay."""
        if key in self._builtin:
            raise ToolError("The built-in tools cannot be removed.")
        self.tools.pop(key, None)
        self._nodes.pop(key, None)
        self._changed()

    def _changed(self):
        if self.on_change:
            self.on_change()

    def user_tools(self):
        """The tools the user made, as documents for the project file."""
        return [tool.to_dict() for key, tool in self.tools.items()
                if key not in self._builtin]

    def load_user_tools(self, documents):
        """
        Replace the user's tools with these (from a project file). One that cannot
        be used — a block it needs is gone — is skipped rather than failing the rest.

        Returns:
            the labels of those skipped
        """
        from workflow_lib import tool_from_dict
        callback, self.on_change = self.on_change, None
        for key in [k for k in self.tools if k not in self._builtin]:
            self.remove(key)
        skipped = []
        for document in documents or []:
            try:
                tool = tool_from_dict(document)
                if tool.key in self._builtin:
                    raise ToolError("A built-in tool has that key.")
                self.add(tool)
            except (ToolError, KeyError, TypeError, StopIteration):
                skipped.append(str(document.get("label", "?")) if isinstance(document, dict) else "?")
        self.on_change = callback
        self._changed()
        return skipped

    def is_builtin(self, key):
        return key in self._builtin

    def node(self, key):
        return self._nodes[key]

    def get(self, key):
        return self.tools.get(key)

    def toolboxes(self):
        """{toolbox: [tool keys]} in menu order: built-in boxes first, then the rest."""
        found = {}
        for tool in self.tools.values():
            if tool.key in HIDDEN_TOOLS:          # still there for saved work, not offered in the menus
                continue
            found.setdefault(tool.toolbox, []).append(tool.key)
        for keys in found.values():           # stable: tools not named in MENU_ORDER keep their order, after
            keys.sort(key=lambda k: MENU_ORDER.index(k) if k in MENU_ORDER else len(MENU_ORDER))
        ordered = {name: found.pop(name) for name in TOOLBOX_ORDER if name in found}
        ordered.update(dict(sorted(found.items())))
        return ordered


def builtin_registry():
    return ToolRegistry(BUILTIN_TOOLS)

scripts/drive_lib/gis.py:
"""
Google sign-in and the file picker.

Everything Google's own JavaScript touches stays in JavaScript. The token
client and the Picker hand back live SDK objects, and Pyodide probes an
incoming object for `next`, `get`, `has` and friends to decide how to wrap
it — the same boundary that breaks Tabulator's components. The shim below does
that work in JS and returns nothing but plain strings and dicts.

What crosses into Python: an access token string, and a picked file's
id/name/mimeType. Nothing else.

The token lives in a JS variable for the life of the page and is never written
to storage. Google Identity Services re-issues it silently when it expires, so
persisting it would add a theft risk and buy nothing.
"""
import js
from pyodide.ffi import to_js
from pyodide.http import pyfetch

# Google's own scripts. GIS carries the token client; api.js carries the Picker.
GIS_SRC = "https://accounts.google.com/gsi/client"
GAPI_SRC = "https://apis.google.com/js/api.js"

# Least privilege: the app sees a file only once the user picks it in Google's
# own dialog, or because the app created it. Not the user's whole Drive.
DRIVE_SCOPE = "https://www.googleapis.com/auth/drive.file"

# `email` buys the signed-in address, and nothing else — no name, no picture,
# no contacts. It is worth the extra consent line because people routinely have
# several Google accounts, and "which Drive am I about to write to?" should not
# be a guess. Drop it and the status just reads "Signed in".
SCOPE = f"openid email {DRIVE_SCOPE}"

USERINFO = "https://www.googleapis.com/oauth2/v3/userinfo"

# What survives a reload: a single flag saying the user opted in, never a
# token. Access tokens last about an hour, and a stored one is a credential
# sitting in localStorage for any XSS to collect — for no benefit, because
# Google re-issues one silently while the grant is live.
_REMEMBER_KEY = "sedStats.google.connected"

_SHIM_ID = "sed-stats-google-shim"
_SHIM_NAME = "__sedStatsGoogle"
_SHIM = """
window.__sedStatsGoogle = (function () {
  let config = null;
  let tokenClient = null;
  let accessToken = null;
  let grantedScopes = "";
  let pickerReady = false;
  let pickerPromise = null;
  let pending = null;

  function loadScript(src) {
    return new Promise(function (resolve, reject) {
      if (document.querySelector('script[src="' + src + '"]')) return resolve();
      const el = document.createElement("script");
      el.src = src;
      el.async = true;
      el.onload = resolve;
      el.onerror = function () { reject(new Error("could not load " + src)); };
      document.head.appendChild(el);
    });
  }

  function waitFor(test, label, timeoutMs) {
    return new Promise(function (resolve, reject) {
      const deadline = Date.now() + (timeoutMs || 15000);
      (function poll() {
        if (test()) return resolve();
        if (Date.now() > deadline) return reject(new Error(label + " never became ready"));
        setTimeout(poll, 50);
      })();
    });
  }

  // Sign-in needs Identity Services and nothing else. The Picker libraries
  // are a second network round trip that used to be awaited here, which put
  // them on the critical path of every sign-in even though most of a session
  // never opens the picker.
  async function ready(cfg) {
    config = cfg;
    await loadScript(cfg.gis_src);
    await waitFor(function () {
      return window.google && google.accounts && google.accounts.oauth2;
    }, "Google Identity Services", 20000);
    return true;
  }

  // Loaded on demand, and warmed in the background once signed in, so the
  // first "Open from Drive" usually finds it already there.
  function ensurePicker() {
    if (!pickerPromise) {
      pickerPromise = (async function () {
        await loadScript(config.gapi_src);
        await waitFor(function () { return window.gapi; }, "gapi", 20000);
        await new Promise(function (resolve) { gapi.load("picker", resolve); });
        pickerReady = true;
      })();
    }
    return pickerPromise;
  }

  function client() {
    if (tokenClient) return tokenClient;
    tokenClient = google.accounts.oauth2.initTokenClient({
      client_id: config.client_id,
      scope: config.scope,
      callback: function (resp) {
        if (resp.error) {
          if (pending) { pending.reject(new Error(resp.error)); pending = null; }
          return;
        }
        accessToken = resp.access_token;
        // Google grants scopes individually: the consent screen has a
        // checkbox per scope, so a "successful" sign-in can come back
        // without Drive access at all. resp.scope is what was actually
        // granted, which is the only thing worth trusting.
        grantedScopes = resp.scope || "";
        // Deliberately not awaited: warming it must not delay sign-in.
        try { ensurePicker(); } catch (e) {}
        if (pending) { pending.resolve(accessToken); pending = null; }
      },
      error_callback: function (err) {
        // Fires when the user closes or blocks the popup, which the success
        // callback never hears about — without this the promise hangs forever.
        if (pending) {
          pending.reject(new Error((err && err.type) || "popup closed"));
          pending = null;
        }
      },
    });
    return tokenClient;
  }

  function signIn(interactive) {
    return new Promise(function (resolve, reject) {
      // Only one request can be outstanding: the token client has a single
      // callback, so a second would strand the first waiting forever.
      if (pending) pending.reject(new Error("superseded by a new sign-in"));
      pending = { resolve: resolve, reject: reject };
      // Google opens a popup and focuses it, which makes the browser fire
      // focus/blur events at once on whatever had focus. Antioch wires Python
      // listeners to almost every element, so doing that here, still inside
      // the Python call that started the sign-in, re-enters Python from within
      // Python — which Pyodide aborts on. A fresh task makes it an ordinary
      // event, like a click. A 0 ms delay keeps the click's user activation,
      // so the popup blocker still lets the popup open.
      setTimeout(function () {
        try {
          client().requestAccessToken({ prompt: interactive ? "consent" : "" });
        } catch (e) {
          if (pending) { pending = null; }
          reject(e);
        }
      }, 0);
    });
  }

  return {
    ready: ready,
    signIn: signIn,
    token: function () { return accessToken; },
    scopes: function () { return grantedScopes; },
    signedIn: function () { return !!accessToken; },

    signOut: function () {
      const token = accessToken;
      accessToken = null;
      grantedScopes = "";
      if (token && window.google && google.accounts && google.accounts.oauth2) {
        // Tell Google to drop the grant too, so signing out actually revokes
        // rather than only forgetting locally.
        try { google.accounts.oauth2.revoke(token); } catch (e) {}
      }
      return true;
    },

    // Resolves to a plain {id, name, mimeType} or null if the user cancelled.
    // `folders` switches it from choosing a file to choosing a destination.
    pick: async function (mimeTypes, folders) {
      if (!accessToken) throw new Error("not signed in");
      await ensurePicker();
      return new Promise(function (resolve, reject) {
        const view = new google.picker.DocsView(
          folders ? google.picker.ViewId.FOLDERS : google.picker.ViewId.DOCS);
        view.setIncludeFolders(true).setSelectFolderEnabled(!!folders);
        // List mode instead of the default grid: the grid fetches a thumbnail
        // per file from googleusercontent, which Firefox blocks cross-origin
        // anyway, so they cost a round trip each and deliver nothing.
        view.setMode(google.picker.DocsViewMode.LIST);
        if (folders) {
          view.setMimeTypes("application/vnd.google-apps.folder");
        } else if (mimeTypes && mimeTypes.length) {
          view.setMimeTypes(mimeTypes.join(","));
        }
        // The picker renders in its own iframe and reports failure only by
        // never opening, so a bad key or a disabled Picker API would leave
        // this promise pending forever and the button spinning.
        let opened = false;
        const timer = setTimeout(function () {
          if (!opened) {
            reject(new Error(
              "the Google file picker did not open after 30s — check that the " +
              "Google " +
              "Picker API is enabled for this project and that the API key " +
              "is valid for this origin"));
          }
        }, 30000);

        const picker = new google.picker.PickerBuilder()
          .addView(view)
          .setOAuthToken(accessToken)
          .setDeveloperKey(config.api_key)
          // Required alongside the drive.file scope: without it the granted
          // token cannot read what the user just picked.
          .setAppId(config.app_id)
          // Picker checks this against the hosting page; without it a page
          // served on a non-default port can silently fail to render.
          .setOrigin(window.location.protocol + "//" + window.location.host)
          .setCallback(function (data) {
            if (data.action === google.picker.Action.LOADED) {
              opened = true;
              clearTimeout(timer);
              return;
            }
            if (data.action === google.picker.Action.CANCEL) {
              clearTimeout(timer);
              return resolve(null);
            }
            if (data.action !== google.picker.Action.PICKED) return;
            clearTimeout(timer);
            const doc = data.docs && data.docs[0];
            resolve(doc ? {id: doc.id, name: doc.name, mimeType: doc.mimeType} : null);
          })
          .build();
        picker.setVisible(true);
      });
    },
  };
})();
"""


def _remember(connected):
    """Record, or clear, the fact that the user connected an account."""
    try:
        storage = js.window.localStorage
        if connected:
            storage.setItem(_REMEMBER_KEY, "1")
        else:
            storage.removeItem(_REMEMBER_KEY)
    except Exception:
        # Private windows and blocked site data make storage throw. Losing
        # the flag only costs one extra click, so it must never be fatal.
        pass


def _was_connected():
    try:
        return js.window.localStorage.getItem(_REMEMBER_KEY) == "1"
    except Exception:
        return False


def _shim():
    """
    The shim object, fetched by name.

    Not `js.window.__sedStatsGoogle`: inside a class body Python mangles any
    leading-double-underscore attribute, so that expression silently becomes
    `js.window._GoogleSession__sedStatsGoogle`. getattr sidesteps the rewrite.
    """
    return getattr(js.window, _SHIM_NAME)


def _ensure_shim():
    # Not `is None`: Pyodide represents JS null as a `jsnull` sentinel, which
    # is not Python None, so `is None` is always False and the script would
    # never be injected. Truthiness is correct for both null and a real node.
    if not js.document.getElementById(_SHIM_ID):
        script = js.document.createElement("script")
        script.id = _SHIM_ID
        script.textContent = _SHIM
        js.document.head.appendChild(script)

    if not hasattr(js.window, _SHIM_NAME):
        raise RuntimeError(
            "the Google sign-in helper script did not run — "
            "check the browser console for a script error")


class GoogleSession:
    """
    One page's Google sign-in.

    Usage:
        session = GoogleSession(client_id=..., api_key=..., app_id=...)
        await session.sign_in()
        picked = await session.pick_file(["text/csv"])
        session.sign_out()
    """

    def __init__(self, client_id: str, api_key: str, app_id: str,
                 scope: str = SCOPE):
        self.client_id = client_id
        self.api_key = api_key
        self.app_id = app_id
        self.scope = scope
        self._ready = False

    @property
    def configured(self) -> bool:
        """Whether a Cloud project has been supplied to sign in against."""
        return bool(self.client_id and self.api_key and self.app_id)

    async def _prepare(self):
        if self._ready:
            return
        if not self.configured:
            raise RuntimeError(
                "Google sign-in is not configured — set client_id, api_key "
                "and app_id from your Google Cloud project")
        _ensure_shim()
        await _shim().ready(to_js({
            "client_id": self.client_id,
            "api_key": self.api_key,
            "app_id": self.app_id,
            "scope": self.scope,
            "gis_src": GIS_SRC,
            "gapi_src": GAPI_SRC,
        }, dict_converter=js.Object.fromEntries))
        self._ready = True

    async def sign_in(self, interactive: bool = True) -> str:
        """Open Google's consent popup and return the access token."""
        await self._prepare()
        token = str(await _shim().signIn(interactive))
        _remember(True)
        return token

    async def restore(self) -> bool:
        """
        Re-establish a previous session without prompting.

        Google issues a fresh token with no UI at all while the grant and the
        browser's Google session are both alive, so a reload does not have to
        look like being signed out. If anything is missing — the grant was
        revoked, the session expired, a popup would be needed — this reports
        failure quietly and the user simply sees the sign-in button.
        """
        if not self.configured or not _was_connected():
            return False
        try:
            await self._prepare()
            await _shim().signIn(False)
            return self.signed_in
        except Exception:
            _remember(False)
            return False

    async def token(self, refresh: bool = False) -> str:
        """
        A live access token.

        Tokens last about an hour. `refresh=True` asks for a new one without
        prompting, which is what a 401 mid-session calls for.
        """
        await self._prepare()
        if refresh or not self.signed_in:
            return str(await _shim().signIn(False))
        return str(_shim().token())

    @property
    def granted_scopes(self):
        """The scopes Google actually granted, as a set."""
        if not self._ready:
            return set()
        return set(str(_shim().scopes() or "").split())

    @property
    def has_drive_access(self) -> bool:
        """
        Whether the granted token can actually reach Drive.

        Consent is per-scope, so signing in successfully proves nothing about
        Drive: declining just the Drive checkbox yields a perfectly valid token
        that 403s on every file call. Checking up front turns that into one
        clear message instead of a failure at each button.

        An empty scope list means Google did not say, not that it refused, so
        that case stays permissive and lets the API be the judge — better a
        clear 403 than a UI that disables itself for no visible reason.
        """
        granted = self.granted_scopes
        return not granted or DRIVE_SCOPE in granted

    @property
    def signed_in(self) -> bool:
        if not self._ready:
            return False
        return bool(_shim().signedIn())

    def sign_out(self):
        """Drop the token and revoke the grant with Google."""
        _remember(False)
        if self._ready:
            _shim().signOut()
        return self

    async def account_email(self):
        """
        The signed-in address, or None if it could not be read.

        Purely for display, so a failure here downgrades the status line rather
        than failing the sign-in that just succeeded.
        """
        try:
            token = await self.token()
            response = await pyfetch(
                USERINFO, headers={"Authorization": f"Bearer {token}"})
            if response.status >= 400:
                return None
            return (await response.json()).get("email")
        except Exception:
            return None

    async def pick_file(self, mime_types=None):
        """
        Show Google's file picker.

        Returns {"id", "name", "mimeType"}, or None if the user cancelled.
        """
        return await self._pick(mime_types, folders=False)

    async def pick_folder(self):
        """
        Show Google's folder picker, for choosing where to save.

        Returns {"id", "name", "mimeType"}, or None if the user cancelled.
        Picking a folder is also what grants the app permission to write into
        it under `drive.file`.
        """
        return await self._pick(None, folders=True)

    async def _pick(self, mime_types, folders):
        await self._prepare()
        picked = await _shim().pick(
            to_js(list(mime_types or [])), folders)
        # Not `is None`: a cancelled picker resolves with JS null, which
        # reaches Python as a `jsnull` sentinel that is not None.
        if not picked:
            return None
        return {"id": str(picked.id), "name": str(picked.name),
                "mimeType": str(picked.mimeType)}

scripts/geo_lib/climate.py:
"""
Weather and climate from Open-Meteo (free, keyless, CORS-open): current conditions at a point,
the average of a variable over a date range at a grid of points (the map's climate raster), and
daily precipitation and temperature averaged over a watershed (the hyetograph's input).
"""
from . import net
from .net import RateLimitedError  # noqa: F401

FORECAST_URL = "https://api.open-meteo.com/v1/forecast"
ARCHIVE_URL = "https://archive-api.open-meteo.com/v1/archive"

# variable -> (Open-Meteo daily parameter, unit, how a range collapses to one value)
VARIABLES = {
    "precipitation": ("precipitation_sum", "mm total", "sum"),
    "temperature": ("temperature_2m_mean", "°C avg", "mean"),
    "wind": ("wind_speed_10m_max", "km/h avg daily max", "mean"),
}
VARIABLE_LABELS = {"precipitation": "Precipitation", "temperature": "Temperature",
                   "wind": "Wind"}

# WMO weather codes, which Open-Meteo uses.
_CODES = {
    0: "Clear sky", 1: "Mainly clear", 2: "Partly cloudy", 3: "Overcast",
    45: "Fog", 48: "Depositing rime fog",
    51: "Light drizzle", 53: "Moderate drizzle", 55: "Dense drizzle",
    56: "Light freezing drizzle", 57: "Dense freezing drizzle",
    61: "Slight rain", 63: "Moderate rain", 65: "Heavy rain",
    66: "Light freezing rain", 67: "Heavy freezing rain",
    71: "Slight snow fall", 73: "Moderate snow fall", 75: "Heavy snow fall", 77: "Snow grains",
    80: "Slight rain showers", 81: "Moderate rain showers", 82: "Violent rain showers",
    85: "Slight snow showers", 86: "Heavy snow showers",
    95: "Thunderstorm", 96: "Thunderstorm with slight hail", 99: "Thunderstorm with heavy hail",
}


def describe_weather_code(code):
    return _CODES.get(int(code), f"Unknown conditions (code {code})")


def parse_current(data):
    """Current conditions from a forecast answer, or None if it has an unexpected shape."""
    current = (data or {}).get("current")
    if not current:
        return None
    try:
        return {"temperature_c": current["temperature_2m"],
                "precipitation_mm": current["precipitation"],
                "wind_speed_kmh": current["wind_speed_10m"],
                "relative_humidity_pct": current["relative_humidity_2m"],
                "description": describe_weather_code(current["weather_code"]),
                "attribution": "Open-Meteo (open-meteo.com)"}
    except KeyError:
        return None


async def fetch_current_weather(lat, lon):
    return parse_current(await net.get_json(
        f"{FORECAST_URL}?latitude={lat}&longitude={lon}"
        f"&current=temperature_2m,precipitation,weather_code,wind_speed_10m,relative_humidity_2m"
        f"&timezone=auto"))


def _coordinates(points):
    return (",".join(f"{lat:.5f}" for lat, _ in points),
            ",".join(f"{lon:.5f}" for _, lon in points))


def _entries(data):
    """One answer object per requested point (a single point comes back as a bare object)."""
    return data if isinstance(data, list) else [data]


def collapse(values, how):
    """The sum or mean of the numbers among `values` (None where there are none)."""
    clean = [v for v in values if v is not None]
    if not clean:
        return None
    return sum(clean) if how == "sum" else sum(clean) / len(clean)


def parse_grid(data, variable):
    """{'values': [one per point, None where missing], 'unit'} from an archive answer."""
    param, unit, how = VARIABLES[variable]
    values = [collapse(((entry or {}).get("daily") or {}).get(param) or [], how)
              for entry in _entries(data)]
    return {"values": values, "unit": unit}


async def fetch_historical_grid(points, start_date, end_date, variable="precipitation"):
    """
    `variable` averaged (or summed) over the dates at each of `points` — (lat, lon) pairs — in
    one request, or None if it failed.
    """
    if variable not in VARIABLES:
        variable = "precipitation"
    lats, lons = _coordinates(points)
    data = await net.get_json(
        f"{ARCHIVE_URL}?latitude={lats}&longitude={lons}&start_date={start_date}"
        f"&end_date={end_date}&daily={VARIABLES[variable][0]}&timezone=UTC")
    return parse_grid(data, variable) if data else None


def average_series(data, params, step="daily"):
    """
    Each parameter in `params` averaged across the points of an archive answer, per time step.

    Returns:
        {'dates': [...], param: [...]}, or None when there is no series
    """
    dates, per_point = None, {p: [] for p in params}
    for entry in _entries(data):
        block = (entry or {}).get(step) or {}
        if dates is None:
            dates = block.get("time")
        for param in params:
            if block.get(param):
                per_point[param].append(block[param])
    if not dates or not any(per_point.values()):
        return None
    out = {"dates": list(dates)}
    for param, series in per_point.items():
        out[param] = [collapse([s[i] for s in series if i < len(s)], "mean")
                      for i in range(len(dates))]
    return out


async def fetch_watershed_series(points, start_date, end_date, hourly=False):
    """
    Precipitation (mm) and temperature (°C) averaged over `points` — a grid inside the
    watershed — one value per day, or per hour with `hourly`. Hourly is Open-Meteo's native
    series; daily precipitation is its daily total.

    Returns:
        {'dates', 'precipitation_mm', 'temperature_c'}, or None
    """
    step = "hourly" if hourly else "daily"
    params = (["precipitation", "temperature_2m"] if hourly
              else ["precipitation_sum", "temperature_2m_mean"])
    lats, lons = _coordinates(points)
    data = await net.get_json(
        f"{ARCHIVE_URL}?latitude={lats}&longitude={lons}&start_date={start_date}"
        f"&end_date={end_date}&{step}={','.join(params)}&timezone=UTC")
    averaged = average_series(data, params, step) if data else None
    if averaged is None:
        return None
    return {"dates": averaged["dates"], "precipitation_mm": averaged[params[0]],
            "temperature_c": averaged[params[1]]}

scripts/geo_lib/geometry.py:
"""
Outlines on the globe: GeoJSON polygons as rings of (lon, lat), whether a point lies inside one,
how big one is, and a handful of points spread over one.

A *polygon* here is a list of rings, the first the outer boundary and any others holes; a
watershed may have several (a MultiPolygon), so the functions work on a list of them.
"""
import math

EARTH_RADIUS_KM = 6371.0088


def polygons_of(geojson):
    """
    The polygons in a GeoJSON Feature, FeatureCollection or geometry, as
    [[ring, ring, ...], ...] with each ring a list of (lon, lat).
    """
    if not geojson:
        return []
    kind = geojson.get("type")
    if kind == "FeatureCollection":
        return [p for f in geojson.get("features", []) for p in polygons_of(f)]
    if kind == "Feature":
        return polygons_of(geojson.get("geometry"))
    coordinates = geojson.get("coordinates")
    if kind == "Polygon":
        return [[[(float(x), float(y)) for x, y, *_ in ring] for ring in coordinates]]
    if kind == "MultiPolygon":
        return [[[(float(x), float(y)) for x, y, *_ in ring] for ring in poly]
                for poly in coordinates]
    return []


def _in_ring(lon, lat, ring):
    """Ray casting: is the point inside this one ring?"""
    inside = False
    n = len(ring)
    j = n - 1
    for i in range(n):
        xi, yi = ring[i]
        xj, yj = ring[j]
        if (yi > lat) != (yj > lat) and lon < (xj - xi) * (lat - yi) / (yj - yi) + xi:
            inside = not inside
        j = i
    return inside


def contains(polygons, lon, lat):
    """Is (lon, lat) inside any polygon — in its outer ring and not in one of its holes?"""
    for rings in polygons:
        if rings and _in_ring(lon, lat, rings[0]) \
                and not any(_in_ring(lon, lat, hole) for hole in rings[1:]):
            return True
    return False


def bounds(polygons):
    """(south, west, north, east) of the polygons, or None when there are none."""
    points = [p for rings in polygons for ring in rings[:1] for p in ring]
    if not points:
        return None
    lons, lats = [p[0] for p in points], [p[1] for p in points]
    return min(lats), min(lons), max(lats), max(lons)


def _ring_area_km2(ring):
    """Signed spherical-excess (trapezoid) area of a ring in km²; the sign follows the winding."""
    n = len(ring)
    if n < 3:
        return 0.0
    total = 0.0
    for i in range(n):
        lon1, lat1 = ring[i]
        lon2, lat2 = ring[(i + 1) % n]
        total += math.radians(lon2 - lon1) * (
            2 + math.sin(math.radians(lat1)) + math.sin(math.radians(lat2)))
    return total * EARTH_RADIUS_KM ** 2 / 2.0


def area_km2(polygons):
    """Area in km² on the sphere — a flat lat/lon estimate is wrong at basin scale."""
    total = 0.0
    for rings in polygons:
        if not rings:
            continue
        area = abs(_ring_area_km2(rings[0])) - sum(abs(_ring_area_km2(h)) for h in rings[1:])
        total += max(area, 0.0)
    return total


def centroid(polygons):
    """The middle of the polygons' bounding box as (lat, lon), or None."""
    box = bounds(polygons)
    if box is None:
        return None
    south, west, north, east = box
    return (south + north) / 2, (west + east) / 2


def grid_inside(polygons, n=8):
    """
    Up to n × n points on a regular grid over the polygons' box that fall inside them, as
    (lat, lon) — the places a watershed-wide average of a weather variable is sampled. A sliver
    that no grid point hits gets its box centre, so there is always at least one point.
    """
    box = bounds(polygons)
    if box is None:
        return []
    south, west, north, east = box
    found = []
    for i in range(n):
        lat = south + (north - south) * (i + 0.5) / n
        for j in range(n):
            lon = west + (east - west) * (j + 0.5) / n
            if contains(polygons, lon, lat):
                found.append((lat, lon))
    if not found:
        found.append(((south + north) / 2, (west + east) / 2))
    return found


def outline_shapes(polygons, name):
    """
    The outer rings as `Polygons` shapes — [(name, [(x, y), ...])], x being longitude and y
    latitude; a watershed with several parts gets "name (2)" and so on.
    """
    shapes = []
    for index, rings in enumerate(polygons):
        if rings:
            label = name if index == 0 else f"{name} ({index + 1})"
            shapes.append((label, list(rings[0])))
    return shapes


def to_geojson(polygons, properties=None):
    """A GeoJSON Feature for the polygons (a Polygon, or a MultiPolygon when there are several)."""
    coords = [[[list(p) for p in ring] for ring in rings] for rings in polygons]
    geometry = ({"type": "Polygon", "coordinates": coords[0]} if len(coords) == 1
                else {"type": "MultiPolygon", "coordinates": coords})
    return {"type": "Feature", "geometry": geometry, "properties": dict(properties or {})}


def round_polygons(polygons, places=5):
    """The polygons with coordinates rounded (1 m is about 5 decimal places), for storing."""
    return [[[(round(x, places), round(y, places)) for x, y in ring] for ring in rings]
            for rings in polygons]


def _simplify_ring(ring, tolerance):
    """Douglas–Peucker on a closed ring (without recursion — a basin outline can have 10⁵ points)."""
    if len(ring) < 5:
        return list(ring)
    open_ring = ring[:-1] if ring[0] == ring[-1] else list(ring)
    n = len(open_ring)
    keep = [False] * n
    keep[0] = keep[n - 1] = True
    stack = [(0, n - 1)]
    while stack:
        first, last = stack.pop()
        (x1, y1), (x2, y2) = open_ring[first], open_ring[last]
        dx, dy = x2 - x1, y2 - y1
        length = math.hypot(dx, dy)
        far, far_at = -1.0, -1
        for i in range(first + 1, last):
            x, y = open_ring[i]
            distance = (math.hypot(x - x1, y - y1) if length == 0
                        else abs(dy * (x - x1) - dx * (y - y1)) / length)
            if distance > far:
                far, far_at = distance, i
        if far > tolerance:
            keep[far_at] = True
            stack.append((first, far_at))
            stack.append((far_at, last))
    kept = [p for p, k in zip(open_ring, keep) if k]
    if len(kept) < 3:
        return list(ring)
    return kept + [kept[0]]


def point_count(polygons):
    return sum(len(ring) for rings in polygons for ring in rings)


def simplify(polygons, max_points=3000):
    """
    The polygons with vertices thinned until there are at most `max_points` (the tolerance is
    doubled from about a metre until they fit), so a stored watershed stays small. A polygon
    already short enough is returned as it is.
    """
    if point_count(polygons) <= max_points:
        return polygons
    tolerance = 1e-5
    thinned = polygons
    while point_count(thinned) > max_points and tolerance < 10:
        thinned = [[_simplify_ring(ring, tolerance) for ring in rings] for rings in polygons]
        tolerance *= 2
    return thinned

scripts/geo_lib/net.py:
"""
The browser's `fetch`, as the few things the map needs from it: JSON, text and bytes.

`js` is imported when first used, so the modules that parse what comes back stay importable (and
testable) outside the browser. Tests replace `FETCH` with a fake.
"""
import json


class RateLimitedError(Exception):
    """A service answered 429: its free allowance is used up. Kept apart from "no data" so the
    message can say to try again later."""


REQUEST_SECONDS = 60       # a request that has not answered by then is given up on, not waited for forever


async def js_fetch(url, seconds=REQUEST_SECONDS):
    import js
    from pyodide.ffi import to_js
    options = to_js({"signal": js.AbortSignal.timeout(int(seconds * 1000))},
                    dict_converter=js.Object.fromEntries)
    return await js.fetch(url, options)


FETCH = js_fetch      # `async (url) -> response` with .status, .ok, .text(), .arrayBuffer(), .blob()


async def get_text(url):
    """The body of `url` as text, or None if the request failed or was refused."""
    try:
        response = await FETCH(url)
    except Exception:
        return None
    if response.status == 429:
        raise RateLimitedError()
    if not response.ok:
        return None
    try:
        return await response.text()
    except Exception:
        return None


async def get_json(url):
    """`url`'s JSON, or None if it could not be fetched or parsed."""
    text = await get_text(url)
    if text is None:
        return None
    try:
        return json.loads(text)
    except ValueError:
        return None

scripts/geo_lib/series.py:
"""
Tables built from what the map fetches, in the layout the hydrology blocks read: a `sample`
column, a `series` column, a `date`, and then the measurements (the same layout as
`gibson_jack_hydro.csv`), so a fetched table goes straight into Time series or Hydrograph.
"""
from .gauges import CFS_TO_M3S
from .pipeline import held_points

COLUMNS = ("sample", "series", "date", "discharge_m3s", "precip_mm", "temperature_c")


def _key(label, hourly):
    """The time a value belongs to: its day, or its hour."""
    return str(label)[:13] if hourly else str(label)[:10]


def _label(key, hourly):
    return f"{key}:00" if hourly else key


def _hourly_means(dates, values):
    """{hour: mean} of readings that may come every 15 minutes."""
    buckets = {}
    for label, value in zip(dates, values):
        if value is not None:
            buckets.setdefault(_key(label, True), []).append(value)
    return {k: sum(v) / len(v) for k, v in buckets.items()}


def hydro_rows(sample, discharge=None, climate=None, hourly=False, series_name=None):
    """
    One row per time step with the discharge at a gauge and the climate over a watershed.

    Args:
        sample: what the first column says (the watershed or the gauge's name)
        discharge: {'dates', 'discharge_cfs', ...} from `gauges`, or None
        climate: {'dates', 'precipitation_mm', 'temperature_c'} from `climate`, or None
        hourly: the series are hourly, so values are matched by hour (15-minute gauge readings
            are averaged into the hour) and the date column carries the time
        series_name: the `series` column; defaults to what the table holds

    Returns:
        rows (dicts, in date order) with only the columns that have something in them
    """
    flow, rain, temp = {}, {}, {}
    if discharge:
        values = [None if v is None else v * CFS_TO_M3S for v in discharge["discharge_cfs"]]
        if hourly:
            flow = _hourly_means(discharge["dates"], values)
        else:
            flow = {_key(d, False): v for d, v in zip(discharge["dates"], values)}
    if climate:
        for label, precip, temperature in zip(climate["dates"], climate["precipitation_mm"],
                                              climate["temperature_c"]):
            rain[_key(label, hourly)] = precip
            temp[_key(label, hourly)] = temperature
    keys = sorted(set(flow) | set(rain) | set(temp))
    kind = "hourly" if hourly else "daily"
    name = series_name or " and ".join(
        part for part, present in (("discharge", flow), ("climate", rain)) if present) or "series"
    rows = []
    for key in keys:
        rows.append({"sample": sample, "series": f"{kind} {name}", "date": _label(key, hourly),
                     "discharge_m3s": _round(flow.get(key)), "precip_mm": _round(rain.get(key)),
                     "temperature_c": _round(temp.get(key))})
    for column in ("discharge_m3s", "precip_mm", "temperature_c"):
        if all(row[column] is None for row in rows):
            for row in rows:
                del row[column]
    return rows


def _round(value):
    return None if value is None else round(float(value), 6)


def extremes_rows(name, held):
    """The highest and lowest points of a watershed as table rows (latitude and longitude columns
    are named so a Sample locations block reads them), or [] if it holds none."""
    return [{"watershed": name, "point": label, "latitude": lat, "longitude": lon,
             "elevation_m": elevation}
            for label, lat, lon, elevation in held_points(held)]


def summary_row(name, result):
    """A one-row table describing a delineated watershed (see `MapsPanel` for the keys)."""
    row = {
        "watershed": name,
        "pour_lat": result.get("pour_lat"),
        "pour_lon": result.get("pour_lon"),
        "area_km2": result.get("area_km2"),
        "method": result.get("method", ""),
        "source": result.get("source", ""),
    }
    if result.get("resolution_m") is not None:
        row["resolution_m"] = result["resolution_m"]
    if result.get("mean_elevation_m") is not None:
        row["mean_elevation_m"] = result["mean_elevation_m"]
        row["min_elevation_m"] = result["min_elevation_m"]
        row["max_elevation_m"] = result["max_elevation_m"]
    return row

