"""Tabulator-backed spreadsheet macro."""
import asyncio
import json

import js

from antioch.elements import Div
from antioch.macros.js_library import JSLibraryMacro

from . import edits

# What the page has to do for the sheet runs in JS: reading the selection, keyboard handling and
# the menus. Tabulator's row, cell and column components must never reach Python: Pyodide probes an
# incoming object for `next`, `get`, `has` and friends to decide how to wrap it, and Tabulator's
# components warn loudly on every unknown property. So this hands back only strings and numbers
# (positions and field names, as JSON), and Python makes every change to the data.
_SHEET_ID = "spreadsheet-lib-sheet-js"
_SHEET_NAME = "__sedStatsSheet"
_SHEET_JS = """
window.__sedStatsSheet = {
  // Where a row is in the data (1-based, in the order getData() returns). Not getPosition():
  // that is the row's place on screen, which differs as soon as the table is sorted, and acting
  // on the wrong row would lose data.
  rowIndex: function (table, row) {
    var all = table.rowManager && table.rowManager.rows;
    var self = row._getSelf ? row._getSelf() : null;
    var at = all && self ? all.indexOf(self) : -1;
    return at >= 0 ? at + 1 : row.getPosition();
  },
  // Positions (1-based, in the data's order) of every row a selection touches.
  positions: function (table) {
    var found = {}, sheet = window.__sedStatsSheet;
    (table.getRanges() || []).forEach(function (range) {
      (range.getRows() || []).forEach(function (row) { found[sheet.rowIndex(table, row)] = true; });
    });
    return JSON.stringify(Object.keys(found).map(Number).sort(function (a, b) { return a - b; }));
  },
  // Fields of every column a selection touches.
  fields: function (table) {
    var found = [];
    (table.getRanges() || []).forEach(function (range) {
      (range.getColumns() || []).forEach(function (column) {
        var field = column.getField();
        if (field && found.indexOf(field) < 0) { found.push(field); }
      });
    });
    return JSON.stringify(found);
  },
  // Every selected block: its rows (0-based, in the data's order) and its column names.
  selection: function (table) {
    var sheet = window.__sedStatsSheet, out = [];
    (table.getRanges() || []).forEach(function (range) {
      var rows = (range.getRows() || []).map(function (row) { return sheet.rowIndex(table, row) - 1; });
      var fields = (range.getColumns() || []).map(function (c) { return c.getField(); }).filter(Boolean);
      if (rows.length && fields.length) { out.push({ rows: rows, fields: fields }); }
    });
    return out;
  },
  // The values of the first selected block, a list of rows, for the clipboard.
  lines: function (table) {
    var ranges = table.getRanges() || [];
    if (!ranges.length) { return []; }
    var fields = (ranges[0].getColumns() || []).map(function (c) { return c.getField(); }).filter(Boolean);
    return (ranges[0].getRows() || []).map(function (row) {
      var data = row.getData();
      return fields.map(function (f) { return data[f] === undefined ? '' : data[f]; });
    });
  },
  // Drop every selection (the table has addRange but no clear, so each is removed in turn).
  clearRanges: function (table) {
    (table.getRanges() || []).slice().forEach(function (range) { range.remove(); });
  },
  // Select every cell.
  selectAll: function (table) {
    var rows = table.getRows('active');
    var fields = table.getColumns().map(function (c) { return c.getField(); }).filter(Boolean);
    if (!rows.length || !fields.length) { return; }
    window.__sedStatsSheet.clearRanges(table);
    // Cells, not rows (addRange takes cells); a row off-screen still has them.
    table.addRange(rows[0].getCell(fields[0]), rows[rows.length - 1].getCell(fields[fields.length - 1]));
  },
  // Put text on the clipboard: the modern call where there is one, else a hidden field and a copy
  // command, either of which is allowed from a key press.
  write: function (text) {
    var fallback = function () {
      var held = document.activeElement;
      var box = document.createElement('textarea');
      box.value = text;
      box.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0;';
      document.body.appendChild(box);
      box.select();
      try { document.execCommand('copy'); } catch (e) { /* nothing more can be done */ }
      document.body.removeChild(box);
      if (held && held.focus) { held.focus(); }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).catch(fallback);
    } else { fallback(); }
  },
  // The first selection: its top-left cell, and how many rows and columns it covers.
  active: function (table) {
    var ranges = table.getRanges() || [];
    if (!ranges.length) { return null; }
    var grid = ranges[0].getStructuredCells ? ranges[0].getStructuredCells() : ranges[0].getCells();
    if (!grid.length || !grid[0].length) { return null; }
    var cell = grid[0][0];
    return { cell: cell, info: { row: window.__sedStatsSheet.rowIndex(table, cell.getRow()), field: cell.getField(),
                                 rows: grid.length, cols: grid[0].length } };
  },
  // Show new data, keeping the scroll position, and select a block of cells if asked.
  replace: function (table, columns, rows, select) {
    var holder = table.rowManager && table.rowManager.getElement ? table.rowManager.getElement() : null;
    var top = holder ? holder.scrollTop : 0;
    if (columns) { table.setColumns(columns); }
    var done = table.setData(rows);
    var finish = function () {
      if (holder) { holder.scrollTop = top; }
      if (!select || !select.field) { return; }
      try {
        var all = table.getRows();
        var fields = table.getColumns().map(function (c) { return c.getField(); }).filter(Boolean);
        var first = all[select.row - 1];
        var last = all[select.row - 1 + Math.max(select.rows, 1) - 1] || first;
        var at = fields.indexOf(select.field);
        var endField = fields[at + Math.max(select.cols, 1) - 1] || select.field;
        if (first && at >= 0) {
          window.__sedStatsSheet.clearRanges(table);
          table.addRange(first.getCell(select.field), last.getCell(endField));
        }
      } catch (e) { /* a selection that cannot be restored is not worth an error */ }
    };
    if (done && done.then) { done.then(finish); } else { finish(); }
  },
  // Menus and the header double-click, which Tabulator takes as options.
  options: function (emit) {
    var send = function (kind, data) { emit(kind, JSON.stringify(data || {})); };
    var here = function (row) { return window.__sedStatsSheet.rowIndex(row.getTable(), row); };
    var rowsOf = function (row) {
      var table = row.getTable(), here = window.__sedStatsSheet.rowIndex(table, row);
      var chosen = JSON.parse(window.__sedStatsSheet.positions(table));
      return chosen.indexOf(here) >= 0 ? chosen : [here];
    };
    var columnsOf = function (column) {
      var table = column.getTable(), here = column.getField();
      var chosen = JSON.parse(window.__sedStatsSheet.fields(table));
      return chosen.indexOf(here) >= 0 ? chosen : [here];
    };
    return {
      columnDefaults: {
        headerDblClick: function (e, column) { send('rename', { field: column.getField() }); },
        headerContextMenu: [
          { label: 'Rename column…', action: function (e, column) { send('rename', { field: column.getField() }); } },
          { label: 'Insert column left…', action: function (e, column) { send('add_column', { field: column.getField(), side: 'left' }); } },
          { label: 'Insert column right…', action: function (e, column) { send('add_column', { field: column.getField(), side: 'right' }); } },
          { separator: true },
          { label: 'Delete column(s)', action: function (e, column) { send('delete_columns', { fields: columnsOf(column) }); } }
        ]
      },
      rowContextMenu: [
        { label: 'Insert row above', action: function (e, row) { send('insert_rows', { position: here(row), below: false, count: 1 }); } },
        { label: 'Insert row below', action: function (e, row) { send('insert_rows', { position: here(row), below: true, count: 1 }); } },
        { label: 'Duplicate row(s)', action: function (e, row) { send('duplicate_rows', { positions: rowsOf(row) }); } },
        { separator: true },
        { label: 'Delete row(s)', action: function (e, row) { send('delete_rows', { positions: rowsOf(row) }); } }
      ]
    };
  },
  // Keyboard and clipboard behaviour a spreadsheet has and Tabulator's range selection lacks:
  // typing on a selected cell replaces its contents, Ctrl+Z / Ctrl+Y undo and redo, and paste
  // is handled here so that a block bigger than the table grows it instead of being cut off.
  install: function (table, holder, emit) {
    var sheet = window.__sedStatsSheet;
    var inside = false;
    var typing = function () {
      var a = document.activeElement;
      return !!a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.tagName === 'SELECT' || a.isContentEditable);
    };
    document.addEventListener('mousedown', function (e) { inside = holder.contains(e.target); }, true);
    holder.addEventListener('keydown', function (e) {
      if (typing()) { return; }
      var key = e.key, mod = e.ctrlKey || e.metaKey;
      if (mod && !e.altKey && (key === 'z' || key === 'Z')) {
        e.preventDefault(); e.stopPropagation(); emit(e.shiftKey ? 'redo' : 'undo', '{}'); return;
      }
      if (mod && !e.altKey && (key === 'y' || key === 'Y')) {
        e.preventDefault(); e.stopPropagation(); emit('redo', '{}'); return;
      }
      var selected = (table.getRanges() || []).length > 0;
      if (mod && !e.altKey && (key === 'a' || key === 'A')) {
        e.preventDefault(); e.stopPropagation(); sheet.selectAll(table); return;
      }
      if (selected && !mod && !e.altKey && (key === 'Delete' || key === 'Backspace')) {
        e.preventDefault(); e.stopPropagation();
        emit('clear', JSON.stringify({ ranges: sheet.selection(table) })); return;
      }
      if (selected && mod && !e.altKey && (key === 'c' || key === 'C' || key === 'x' || key === 'X')) {
        e.preventDefault(); e.stopPropagation();
        sheet.write(emit('format', JSON.stringify({ lines: sheet.lines(table) })));
        if (key === 'x' || key === 'X') { emit('clear', JSON.stringify({ ranges: sheet.selection(table), cut: true })); }
        return;
      }
      if (!mod && !e.altKey && key.length === 1) {
        var active = sheet.active(table);
        if (!active) { return; }
        e.preventDefault(); e.stopPropagation();
        active.cell.edit(true);
        var input = active.cell.getElement().querySelector('input');
        if (input) { input.value = key; input.setSelectionRange(key.length, key.length); }
      }
    }, true);
    // Copy and cut chosen from a menu rather than the keyboard.
    ['copy', 'cut'].forEach(function (name) {
      window.addEventListener(name, function (e) {
        if (!inside && !holder.contains(document.activeElement)) { return; }
        if (typing() || !(table.getRanges() || []).length || !e.clipboardData) { return; }
        e.preventDefault(); e.stopImmediatePropagation();
        e.clipboardData.setData('text/plain', emit('format', JSON.stringify({ lines: sheet.lines(table) })));
        if (name === 'cut') { emit('clear', JSON.stringify({ ranges: sheet.selection(table), cut: true })); }
      }, true);
    });
    window.addEventListener('paste', function (e) {
      if (!inside && !holder.contains(document.activeElement)) { return; }
      if (typing()) { return; }
      var data = e.clipboardData;
      var text = data ? data.getData('text/plain') : null;
      if (text === null || text === undefined) { return; }
      e.preventDefault(); e.stopImmediatePropagation();
      var active = sheet.active(table);
      emit('paste', JSON.stringify(Object.assign({ text: text }, active ? active.info : {})));
    }, true);
  }
};
"""


def _ensure_sheet_js():
    # Not `is None`: Pyodide represents JS null as a `jsnull` sentinel, which
    # is not Python None, so `is None` is always False and the script would
    # never be injected. Truthiness is correct for both null and a real node.
    if not js.document.getElementById(_SHEET_ID):
        script = js.document.createElement("script")
        script.id = _SHEET_ID
        script.textContent = _SHEET_JS
        js.document.head.appendChild(script)

    if not hasattr(js.window, _SHEET_NAME):
        raise RuntimeError(
            "the spreadsheet helper script did not run — "
            "check the browser console for a script error")


def _sheet_js():
    """
    The shim, fetched by name.

    Not `js.window.__sedStatsSheet`: inside a class body Python mangles any
    leading-double-underscore attribute, so that expression silently becomes
    `js.window._TabulatorSheet__sedStatsSheet`. getattr sidesteps the rewrite.
    """
    return getattr(js.window, _SHEET_NAME)


class TabulatorSheet(JSLibraryMacro):
    """
    Editable spreadsheet backed by the Tabulator JS library.

    Everything a spreadsheet lets you do to its cells is here: type to replace a cell, double-click
    or Enter to edit, Delete to clear, arrow keys and Tab to move, paste that grows the sheet,
    insert, duplicate and delete rows and columns, rename a column, undo and redo. Every change
    goes through `edits` and is kept so it can be undone.

    Usage:
        sheet = TabulatorSheet(data=[{"a": 1, "b": 2}], height="400px")
        DOM.add(sheet.element)

        @when(sheet.events.data_change)
        def on_change(sender, data):
            ...

    Two hooks the page sets: `prompt`, `async (title, label, value) -> text or None`, asks for a
    column's name; `on_message`, `(text)`, hears what an edit did or why it could not.
    """

    UNDO_LIMIT = 40

    def __init__(self, data=None, columns=None, height="400px", options=None,
                 editable=True, sortable=True, **kwargs):
        """
        Args:
            data: List of row dicts
            columns: Tabulator column definitions; if None, columns are
                     auto-generated from the data (and regenerate on set_data)
            height: CSS height of the table; falsy sizes to content
            options: Extra Tabulator options merged over the defaults
            editable: Whether auto-generated columns accept typing
            sortable: Whether auto-generated columns sort on their header
        """
        super().__init__(macro_type="tabulator_sheet", **kwargs)

        self._set_state(
            data=data or [],
            columns=columns,
            height=height,
            options=options or {},
            editable=editable,
            sortable=sortable,
        )

        self._create_event('data_change')

        # Tabulator's constructor returns before the table exists: it builds
        # asynchronously and announces itself with `tableBuilt`. Anything that
        # touches the rendered table has to wait for that, so a redraw asked
        # for too early is remembered rather than thrown at a half-built table.
        self._built = False
        self._pending_redraw = False

        # The column order is kept apart from the rows, so a sheet with no rows still has columns
        # and a column with nothing in it is not lost. Rows and order are never changed in place:
        # each edit makes new ones, so a snapshot for undo is just a reference.
        self._order = edits.columns_of(
            data or [], [c["field"] for c in (columns or []) if "field" in c])
        self._current = (data or [], list(self._order))
        self._undo = []
        self._redo = []
        self.prompt = None
        self.on_message = None

        self._init_macro()

    def _get_library_dependencies(self):
        return {
            'scripts': ['antioch/lib/vendor/tabulator.min.js'],
            'stylesheets': ['antioch/lib/vendor/tabulator.min.css'],
        }

    def _get_library_global_name(self):
        return 'Tabulator'

    def _create_elements(self):
        container = self._register_element(
            'container', self._create_container({"width": "100%"})
        )
        holder = self._register_element('holder', Div())
        holder.set_attribute("id", f"tabulator_{self._id}")
        container.add(holder)
        return container

    def _column_definitions(self):
        columns = self._get_state('columns')
        if columns:
            return columns
        column = {'headerSort': self._get_state('sortable'), 'minWidth': 110}
        if self._get_state('editable'):
            column['editor'] = 'input'
            # Open with the existing value selected, so typing replaces it.
            column['editorParams'] = {'selectContents': True}
        return [{'title': field, 'field': field, **column}
                for field in edits.columns_of(self._get_state('data'), self._order)]

    def _build_options(self):
        options = {
            'data': self._get_state('data'),
            'layout': 'fitColumns',
            'columns': self._column_definitions(),
            # A row-number gutter, as a spreadsheet has. With row selection on,
            # Tabulator's range module otherwise claims the first visible
            # column as its row header — skipping it in every range and
            # dropping it from the copy. Its own column keeps the first data
            # column being data.
            'rowHeader': {
                'formatter': 'rownum',
                'hozAlign': 'center',
                'headerSort': False,
                'resizable': False,
                'frozen': True,
                'width': 44,
            },
            'nestedFieldSeparator': False,
            'selectableRange': True,
            'selectableRangeColumns': True,
            'selectableRangeRows': True,
            'selectableRangeClearCells': self._get_state('editable'),
            # An emptied cell is "", as a cell that was never filled is.
            'selectableRangeClearCellsValue': '',
            'clipboard': True,
            'clipboardCopyRowRange': 'range',
            # Cells as they are, so what is copied can be pasted straight back; a header row
            # would land in the data. (Pasting is handled by the shim, which can grow the sheet.)
            'clipboardCopyConfig': {'columnHeaders': False, 'rowHeaders': False},
            # Single click selects, so editing needs the second one — the
            # spreadsheet convention, and the only way both gestures fit. Typing on a
            # selected cell also starts an edit (see the shim).
            'editTriggerEvent': 'dblclick',
            'editorEmptyValue': '',
            # Tabulator warns that a sortable header and column range selection
            # fight over the same click; confining sorting to the icon is the
            # resolution it recommends.
            'headerSortClickElement': 'icon',
        }
        height = self._get_state('height')
        if height:
            options['height'] = height
        options.update(self._get_state('options'))
        return options

    def _create_js_instance(self):
        _ensure_sheet_js()
        holder = self._get_element('holder')
        self._emit_proxy = self._create_proxy(self._handle_emit)
        options = self._to_js(self._build_options())
        js.Object.assign(options, _sheet_js().options(self._emit_proxy))
        table = js.Tabulator.new(holder._dom_element, options)
        # dataChanged passes the plain data array; Tabulator components (cell,
        # row) must never cross into Python — Pyodide's capability probes
        # trigger Tabulator's unknown-property warnings.
        table.on('dataChanged', self._create_proxy(self._handle_data_changed))
        table.on('tableBuilt', self._create_proxy(self._handle_table_built))
        _sheet_js().install(table, holder._dom_element, self._emit_proxy)
        return table

    def _handle_table_built(self, *args):
        self._built = True
        if self._pending_redraw:
            self._pending_redraw = False
            self.redraw()

    def _handle_data_changed(self, data):
        """Tabulator changed a cell (the user typed, cleared or pasted over it)."""
        rows = [{k: ("" if v is None else v) for k, v in row.items()} for row in data.to_py()]
        if rows == self._current[0]:
            return                      # nothing differs: an echo of a change already taken
        self._remember_for_undo()
        self._set_state(data=rows)
        self._current = (rows, list(self._order))
        self._fire_event('data_change', rows)

    # ========== Public API ==========

    def get_data(self):
        """Current table contents as a list of row dicts."""
        if not self.is_initialized:
            return list(self._get_state('data'))
        return self.js_instance.getData().to_py()

    @property
    def columns(self):
        """The column names, in order."""
        return list(self._order)

    def set_data(self, data, columns=None):
        """
        Replace table contents, regenerating auto columns from the new data. A new document:
        what could be undone belongs to the old one, so the history starts over.
        """
        self._undo.clear()
        self._redo.clear()
        self._order = edits.columns_of(data, columns if columns is not None else [])
        self._set_state(data=data)
        self._current = (data, list(self._order))
        self._show(data)
        self._fire_event('data_change', data)
        return self

    # ---- editing: each of these makes a new state, which can be undone

    def add_row(self):
        """Insert a blank row below the selection, or at the end if none."""
        if not self.is_initialized:
            return self
        rows = self._rows()
        positions = self._selected_positions()
        index = max(positions) if positions else len(rows)
        self._apply(edits.insert_rows(rows, self._order, index),
                    select=self._cell(index + 1, 0))
        return self

    def delete_selected_rows(self):
        """
        Remove every row touched by the current selection.

        Returns the number deleted, so a caller can say nothing was selected
        rather than silently doing nothing.
        """
        if not self.is_initialized:
            return 0
        positions = self._selected_positions()
        if not positions:
            return 0
        self._apply(edits.delete_rows(self._rows(), [p - 1 for p in positions]))
        return len(positions)

    def delete_selected_columns(self):
        """Remove every column touched by the current selection; the number removed."""
        if not self.is_initialized:
            return 0
        fields = [f for f in json.loads(str(_sheet_js().fields(self.js_instance))) if f in self._order]
        if not fields:
            return 0
        rows, order = edits.delete_columns(self._rows(), self._order, fields)
        self._apply(rows, order)
        return len(fields)

    def undo(self):
        """Undo the last change; False when there is nothing to undo."""
        return self._travel(self._undo, self._redo)

    def redo(self):
        """Redo what was undone; False when there is nothing to redo."""
        return self._travel(self._redo, self._undo)

    async def request_add_column(self, field=None, side="right"):
        """Ask for a name and add a column beside `field` (the selected column, else the end)."""
        name = await self._ask_name("New column", "")
        if name is None:
            return None
        if field is None:
            chosen = [f for f in json.loads(str(_sheet_js().fields(self.js_instance)))
                      if f in self._order] if self.is_initialized else []
            field = chosen[-1] if chosen else None
        index = None
        if field in self._order:
            index = self._order.index(field) + (1 if side == "right" else 0)
        rows, order, used = edits.add_column(self._rows(), self._order, name, index)
        self._apply(rows, order, select=self._cell(1, order.index(used)) if rows else None)
        self._say(f"Added the column '{used}'.")
        return used

    async def request_rename(self, field):
        """Ask for a new name for a column and rename it."""
        if field not in self._order:
            return None
        name = await self._ask_name("Rename column", field)
        if name is None or name.strip() == field:
            return None
        try:
            rows, order = edits.rename_column(self._rows(), self._order, field, name)
        except ValueError as error:
            self._say(str(error))
            return None
        self._apply(rows, order)
        self._say(f"Renamed '{field}' to '{name.strip()}'.")
        return name.strip()

    # ---- the rest

    def redraw(self):
        """Recompute layout. Needed after the table becomes visible again:
        Tabulator sizes itself on render and measures zero while hidden."""
        if not self.is_initialized:
            return self
        if not self._built:
            self._pending_redraw = True
            return self
        try:
            self.js_instance.redraw(True)
        except Exception:
            # A table torn down between the request and the call has nothing
            # to redraw, and a failed relayout is never worth an error box.
            pass
        return self

    @property
    def is_ready(self):
        return self.is_initialized and self._built

    # ========== internals ==========

    def _rows(self):
        return list(self._get_state('data'))

    def _cell(self, row, column_index, rows=1, cols=1):
        """A block of cells to select afterwards: 1-based row, 0-based column."""
        if not self._order:
            return None
        column_index = max(0, min(column_index, len(self._order) - 1))
        return {"row": row, "field": self._order[column_index], "rows": rows, "cols": cols}

    def _selected_positions(self):
        return json.loads(str(_sheet_js().positions(self.js_instance)))

    def _say(self, text):
        if self.on_message:
            self.on_message(text)

    async def _ask_name(self, title, value):
        if self.prompt is None:
            return value or None
        return await self.prompt(title, "Column name", value)

    def _remember_for_undo(self):
        self._undo.append(self._current)
        del self._undo[:-self.UNDO_LIMIT]
        self._redo.clear()

    def _show(self, rows, select=None):
        """Put rows (and the columns) on the page."""
        if not self.is_initialized:
            return
        columns = None if self._get_state('columns') else self._to_js(self._column_definitions())
        _sheet_js().replace(self.js_instance, columns, self._to_js(rows),
                            self._to_js(select) if select else None)

    def _apply(self, rows, columns=None, select=None):
        """Make an edit: new rows (and columns), shown, kept for undo, announced."""
        self._remember_for_undo()
        if columns is not None:
            self._order = list(columns)
        self._set_state(data=rows)
        self._current = (rows, list(self._order))
        self._show(rows, select)
        self._fire_event('data_change', rows)

    def _travel(self, source, sink):
        if not source:
            return False
        sink.append(self._current)
        rows, order = source.pop()
        self._order = list(order)
        self._set_state(data=rows)
        self._current = (rows, list(order))
        self._show(rows)
        self._fire_event('data_change', rows)
        return True

    def _handle_emit(self, kind, payload):
        """What the shim reports: a key, a paste or a menu choice, as text."""
        kind = str(kind)
        try:
            data = json.loads(str(payload) or "{}")
        except ValueError:
            return ""
        rows, order = self._rows(), self._order
        if kind == "format":
            # The clipboard's text for some cells: one place decides how they are written.
            return edits.to_clipboard(data.get("lines", []))
        if kind == "undo":
            if not self.undo():
                self._say("Nothing to undo.")
        elif kind == "redo":
            if not self.redo():
                self._say("Nothing to redo.")
        elif kind == "paste":
            self._paste(data)
        elif kind == "clear":
            self._clear(data)
        elif kind == "rename":
            asyncio.ensure_future(self.request_rename(data.get("field")))
        elif kind == "add_column":
            asyncio.ensure_future(self.request_add_column(data.get("field"), data.get("side", "right")))
        elif kind == "delete_columns":
            fields = [f for f in data.get("fields", []) if f in order]
            if fields:
                new_rows, new_order = edits.delete_columns(rows, order, fields)
                self._apply(new_rows, new_order)
                self._say(f"Deleted {len(fields)} column{'s' if len(fields) != 1 else ''}.")
        elif kind == "insert_rows":
            # `position` is the clicked row, 1-based: above it is that index less one, below it is
            # the index just after.
            at = int(data.get("position", 1)) - (0 if data.get("below") else 1)
            count = max(1, int(data.get("count", 1)))
            self._apply(edits.insert_rows(rows, order, at, count), select=self._cell(at + 1, 0))
        elif kind == "duplicate_rows":
            positions = [int(p) - 1 for p in data.get("positions", [])]
            self._apply(edits.duplicate_rows(rows, positions))
        elif kind == "delete_rows":
            positions = [int(p) - 1 for p in data.get("positions", [])]
            self._apply(edits.delete_rows(rows, positions))
            self._say(f"Deleted {len(positions)} row{'s' if len(positions) != 1 else ''}.")

    def _clear(self, data):
        """Empty the selected cells (Delete, Backspace, or the second half of a cut): one undo step."""
        blocks = data.get("ranges", [])
        rows, count = edits.clear_cells(self._rows(), blocks)
        if count:
            first = blocks[0]
            span = sorted(first["rows"])
            contiguous = span == list(range(span[0], span[0] + len(span)))
            select = (self._cell(span[0] + 1, self._order.index(first["fields"][0]), len(span), len(first["fields"]))
                      if contiguous and first["fields"][0] in self._order else None)
            self._apply(rows, select=select)
        self._say(f"{'Cut' if data.get('cut') else 'Cleared'} {count:,} cell{'s' if count != 1 else ''}."
                  if count else "Nothing to clear.")

    def _paste(self, data):
        cells = edits.parse_clipboard(data.get("text", ""))
        if not cells:
            return
        order = self._order
        field = data.get("field")
        column_index = order.index(field) if field in order else 0
        row = max(0, int(data.get("row", 1)) - 1)
        before = (len(self._rows()), len(order))
        rows, new_order, written = edits.paste_block(
            self._rows(), order, cells, row, column_index,
            int(data.get("rows", 1)), int(data.get("cols", 1)))
        self._apply(rows, new_order, select=self._cell(written[0] + 1, written[1], written[2], written[3]))
        grown = []
        if len(rows) > before[0]:
            grown.append(f"{len(rows) - before[0]} row{'s' if len(rows) - before[0] != 1 else ''}")
        if len(new_order) > before[1]:
            grown.append(f"{len(new_order) - before[1]} column{'s' if len(new_order) - before[1] != 1 else ''}")
        self._say(f"Pasted {written[2]} × {written[3]} cells" + (f", adding {' and '.join(grown)}." if grown else "."))

scripts/spreadsheet_lib/importers.py:
"""Parsers that turn uploaded spreadsheet files into a list of row dicts."""
import csv
import io
from datetime import date, datetime, time

SUPPORTED_EXTENSIONS = (".csv", ".xls", ".xlsx")


def _plain(value):
    """
    A cell as the sheet holds it. An Excel date cell arrives as a datetime; it becomes the text
    "2021-01-16" (or "2021-01-16 13:45:00" with a time), which the date-reading tools understand, the
    grid shows as it is, and a project file can store (a datetime cannot be written to one).
    """
    if isinstance(value, datetime):
        if value.hour or value.minute or value.second or value.microsecond:
            return value.replace(microsecond=0).isoformat(sep=" ")
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, time):
        return value.replace(microsecond=0).isoformat()
    return value


def _rows_to_dicts(rows):
    rows = [row for row in rows if any(cell not in (None, "") for cell in row)]
    if not rows:
        return []

    headers = [
        str(header) if header not in (None, "") else f"column_{i + 1}"
        for i, header in enumerate(rows[0])
    ]
    result = []
    for row in rows[1:]:
        padded = list(row) + [""] * (len(headers) - len(row))
        result.append({
            header: "" if value is None else _plain(value)
            for header, value in zip(headers, padded)
        })
    return result


def parse_csv(text: str):
    return _rows_to_dicts(list(csv.reader(io.StringIO(text))))


def parse_xlsx(content: bytes):
    from openpyxl import load_workbook

    workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
    sheet = workbook.active
    return _rows_to_dicts([list(row) for row in sheet.iter_rows(values_only=True)])


def _xls_value(book, cell):
    """A cell of an .xls file: a date cell as a datetime (xlrd gives only an Excel serial number)."""
    import xlrd
    if cell.ctype == xlrd.XL_CELL_DATE:
        try:
            return xlrd.xldate.xldate_as_datetime(cell.value, book.datemode)
        except (ValueError, xlrd.xldate.XLDateError):
            return cell.value
    return cell.value


def parse_xls(content: bytes):
    import xlrd

    book = xlrd.open_workbook(file_contents=content)
    sheet = book.sheet_by_index(0)
    return _rows_to_dicts([[_xls_value(book, sheet.cell(i, j)) for j in range(sheet.ncols)]
                           for i in range(sheet.nrows)])


def parse_file(filename: str, content):
    lower = filename.lower()
    if lower.endswith(".csv"):
        return parse_csv(content)
    if lower.endswith(".xlsx"):
        return parse_xlsx(content)
    if lower.endswith(".xls"):
        return parse_xls(content)
    raise ValueError(
        f"Unsupported file type: {filename} (supported: {', '.join(SUPPORTED_EXTENSIONS)})"
    )

def rows_to_csv(rows) -> str:
    """
    Turn row dicts back into CSV text.

    The inverse of `parse_csv`, for handing the grid's contents to something
    that wants a file. Column order follows the first row, with any key a later
    row introduces appended, so a ragged set of rows still round-trips.
    """
    rows = list(rows)
    if not rows:
        return ""

    headers = list(rows[0].keys())
    seen = set(headers)
    for row in rows[1:]:
        for key in row:
            if key not in seen:
                seen.add(key)
                headers.append(key)

    buffer = io.StringIO()
    # Excel and Sheets both expect CRLF, and csv defaults to it; asking for it
    # explicitly keeps the output the same wherever this runs.
    writer = csv.writer(buffer, lineterminator="\r\n")
    writer.writerow(headers)
    for row in rows:
        writer.writerow(["" if row.get(h) is None else row.get(h, "")
                         for h in headers])
    return buffer.getvalue()

scripts/ui_lib/fields.py:
"""Form field groups used to build wizard panels."""
from antioch.elements import Div, Input, Label, Option, Select, Span


def set_select_options(select, values, empty_text="—"):
    """
    Replace a Select's options, keeping the current choice if it survives.

    Mirrors CheckboxGroup.set_options: refreshing the spreadsheet should not
    silently reset what the user picked.
    """
    previous = select.value
    select.clear()
    if not values:
        select.add(Option(empty_text, value=""))
        return select

    for value in values:
        select.add(Option(str(value), value=value))
    if previous in [str(v) for v in values]:
        select.value = previous
    return select


class CheckboxGroup:
    """
    A scrollable list of checkboxes with select-all / select-none shortcuts.

    Options can be replaced at runtime; previously checked values stay checked
    if they still exist, so refreshing the spreadsheet doesn't reset choices.
    """

    def __init__(self, options=None, all_checked=True, height="150px",
                 empty_text="Nothing to choose", on_change=None):
        self._all_checked = all_checked
        self._empty_text = empty_text
        self._boxes = {}
        # Called whenever the checked set changes, so callers can react to the
        # selection (showing options that only apply to certain choices).
        self.on_change = on_change

        self._list = Div(style={
            "max-height": height, "overflow-y": "auto",
            "border": "1px solid #ddd", "border-radius": "4px",
            "padding": "6px", "background-color": "#fff",
        })

        self._select_all = Span("select all", style={
            "cursor": "pointer", "color": "#0066cc", "font-size": "12px",
            "text-decoration": "underline",
        })
        self._select_none = Span("select none", style={
            "cursor": "pointer", "color": "#0066cc", "font-size": "12px",
            "margin-left": "12px", "text-decoration": "underline",
        })
        self._select_all.on_click(lambda e: self.set_all(True))
        self._select_none.on_click(lambda e: self.set_all(False))

        self.element = Div(
            Div(self._select_all, self._select_none, style={"margin-bottom": "4px"}),
            self._list,
        )

        self.set_options(options or [])

    def set_options(self, options):
        previous = {value: box._dom_element.checked for value, box in self._boxes.items()}
        self._boxes = {}
        self._list._dom_element.innerHTML = ""

        if not options:
            self._list.add(Span(self._empty_text, style={"color": "#888", "font-size": "13px"}))
            return

        for value in options:
            box = Input("checkbox", style={"margin-right": "8px"})
            box._dom_element.checked = previous.get(value, self._all_checked)
            box.on('change', lambda e: self._changed())
            self._boxes[value] = box
            self._list.add(Div(
                Label(box, Span(str(value)), style={
                    "display": "flex", "align-items": "center",
                    "font-size": "13px", "padding": "2px 0", "cursor": "pointer",
                }),
            ))
        self._changed()

    def _changed(self):
        if self.on_change:
            self.on_change(self.values())

    def set_all(self, checked):
        for box in self._boxes.values():
            box._dom_element.checked = checked
        # Setting .checked in code does not fire a DOM change event.
        self._changed()

    def values(self):
        return [value for value, box in self._boxes.items() if box._dom_element.checked]

    @property
    def options(self):
        return list(self._boxes.keys())


def labeled(label_text, control, hint=None):
    """A wizard form row: bold label, control, optional hint line."""
    children = [
        Label(label_text, style={
            "display": "block", "font-weight": "500",
            "margin-bottom": "4px", "font-size": "14px",
        }),
        control,
    ]
    if hint:
        children.append(Div(hint, style={
            "color": "#6c757d", "font-size": "12px", "margin-top": "3px",
        }))
    return Div(*children, style={"margin-bottom": "16px"})

scripts/ui_lib/ribbon.py:
"""Toolbar of tool buttons, one per action."""
from antioch.elements import Div
from antioch.event import when
from antioch.macros.base import Macro
from component_lib import ButtonInfo

class Ribbon(Macro):
    """
    Horizontal button bar. Each tool is (key, label); pressing one fires
    `select` with that key, and the pressed tool renders as active.

        ribbon = Ribbon(tools=[("mds", "MDS")])

        @when(ribbon.events.select)
        def on_select(sender, key):
            ...
    """

    def __init__(self, tools=None, **kwargs):
        super().__init__(macro_type="ribbon", **kwargs)

        self._buttons = {}
        self._active = None

        self._create_event('select')
        self._init_macro()

        for key, label in (tools or []):
            self.add_tool(key, label)

    def _create_elements(self):
        return self._register_element('container', self._create_container({
            "display": "flex", "flex-wrap": "wrap", "gap": "8px",
            "padding": "10px", "background-color": "#f8f9fa",
            "border": "1px solid #dee2e6", "border-radius": "6px",
            "margin-bottom": "16px",
        }))

    def add_tool(self, key, label):
        button = ButtonInfo(label, size="small", active=key == self._active)
        @when(button.events.click)
        def on_click(sender, *args):
            self.select(key)
        self._buttons[key] = button
        self._get_element('container').add(button)
        return self

    def select(self, key):
        """Select a tool, or pass None to clear the selection."""
        self._active = key
        for tool_key, button in self._buttons.items():
            active = tool_key == key
        if key is not None:
            self._fire_event('select', key)
        return self

    @property
    def active(self):
        return self._active

scripts/ui_lib/tabs.py:
"""Tab bar whose panels stay mounted.

Antioch's own Tabs macro swaps content by clearing the container's innerHTML,
which detaches JS-backed widgets (Tabulator, Plotly) and leaves them to
re-render on reattach. Toggling `display` instead keeps every panel in the
DOM, so those widgets only ever need a redraw, never a rebuild.
"""
from antioch.elements import Button, Div
from antioch.macros.base import Macro


class TabItem:
    def __init__(self, title, content):
        self.title = title
        self.content = content
        self.button = None


class TabView(Macro):
    """
    Horizontal tabs.

        view = TabView(tabs=[TabItem("Outputs", outputs_div)])
        DOM.add(view.element)

        @when(view.events.change)
        def on_change(sender, tab, index):
            ...
    """

    def __init__(self, tabs=None, active=0, fill=False, **kwargs):
        """
        Args:
            fill: Stretch to the parent's height with the tab bar pinned and
                  the panel area taking the remaining space. Panels are then
                  responsible for their own scrolling.
        """
        self._fill = fill
        super().__init__(macro_type="tabview", **kwargs)

        self._tabs = []
        self._active_index = -1

        self._create_event('change')
        self._init_macro()

        for tab in (tabs or []):
            self.add_tab(tab)
        if self._tabs:
            self.set_active(active)

    def _create_elements(self):
        container_style = {"width": "100%"}
        content_style = {
            "border": "1px solid #dee2e6", "border-top": "none",
            "border-radius": "0 0 6px 6px", "padding": "16px",
            "background-color": "#fff",
        }
        if self._fill:
            container_style.update({
                "display": "flex", "flex-direction": "column",
                "height": "100%", "min-height": "0",
            })
            # min-height:0 lets this shrink below its content so the panel,
            # not the page, is what scrolls.
            content_style.update({
                "flex": "1", "min-height": "0", "overflow": "hidden",
                "border-radius": "0", "padding": "0",
            })

        container = self._register_element('container', self._create_container(container_style))
        self._register_element('bar', Div(style={
            "display": "flex", "flex-wrap": "wrap", "gap": "2px",
            "border-bottom": "2px solid #dee2e6", "margin-bottom": "0",
            "flex-shrink": "0",
        }))
        self._register_element('content', Div(style=content_style))
        container.add(self._get_element('bar'), self._get_element('content'))
        return container

    def _tab_button(self, tab, index):
        button = Button(tab.title, style={
            "padding": "9px 18px", "border": "none", "cursor": "pointer",
            "font-size": "14px", "background": "transparent", "color": "#495057",
            "border-bottom": "3px solid transparent", "margin-bottom": "-2px",
        })
        button.on_click(lambda e, i=index: self.set_active(i))
        return button

    def add_tab(self, tab):
        index = len(self._tabs)
        tab.button = self._tab_button(tab, index)
        self._get_element('bar').add(tab.button)

        wrapper_style = {"display": "none"}
        if self._fill:
            wrapper_style.update({"height": "100%", "min-height": "0"})
        wrapper = Div(tab.content, style=wrapper_style)
        tab.content = wrapper
        self._get_element('content').add(wrapper)

        self._tabs.append(tab)
        if len(self._tabs) == 1:
            self.set_active(0)
        return self

    def set_active(self, index):
        if not (0 <= index < len(self._tabs)) or index == self._active_index:
            return self
        self._active_index = index

        for i, tab in enumerate(self._tabs):
            active = i == index
            tab.content.style.display = "block" if active else "none"
            if tab.button:
                tab.button.style.color = "#0066cc" if active else "#495057"
                tab.button.style.font_weight = "600" if active else "400"
                tab.button.style.border_bottom = (
                    "3px solid #0066cc" if active else "3px solid transparent"
                )

        self._fire_event('change', self._tabs[index], index)
        return self

    def clear_tabs(self):
        self._get_element('bar')._dom_element.innerHTML = ""
        self._get_element('content')._dom_element.innerHTML = ""
        self._tabs = []
        self._active_index = -1
        return self

    @property
    def tabs(self):
        return list(self._tabs)

    @property
    def active_index(self):
        return self._active_index

scripts/ui_lib/wizard.py:
"""Stepped options panel that generates output only when asked."""
import js

from antioch.elements import Button, Div, H3, Span
from antioch.macros.base import Macro

_CSS_ID = "ui-lib-wizard-css"

# Inline styles can't express media queries, and a 160px sidebar leaves too
# little room for the form on a phone. Below 640px the nav becomes a
# horizontal strip above the panel instead, as dzToolBox's dialogs do.
_CSS = """
@media (max-width: 640px) {
  .wizard-body { flex-direction: column !important; }
  .wizard-sidebar {
    width: 100% !important;
    display: flex;
    overflow-x: auto;
    border-right: none !important;
    border-bottom: 1px solid #e9ecef;
  }
  .wizard-sidebar button {
    width: auto !important;
    white-space: nowrap;
    border-left: none !important;
    border-bottom: 3px solid transparent;
  }
}
"""


def _ensure_css():
    # Not `is None`: Pyodide represents JS null as a `jsnull` sentinel, so
    # `is None` never matched and this re-injected the style on every call.
    if not js.document.getElementById(_CSS_ID):
        style = js.document.createElement("style")
        style.id = _CSS_ID
        style.textContent = _CSS
        js.document.head.appendChild(style)


class WizardPanel:
    def __init__(self, title, content, description=None):
        self.title = title
        self.content = content
        self.description = description
        self.nav_button = None


class Wizard(Macro):
    """
    Sidebar-stepped form. Panels stay mounted and are shown/hidden, so field
    values survive switching between steps.

    Fires `submit` when the action button is pressed; the handler is
    responsible for reading the panels' fields and doing the work.

        wizard = Wizard(panels=[WizardPanel("Options", options_div)],
                        submit_text="Create graphs")

        @when(wizard.events.submit)
        def on_submit(sender):
            ...
    """

    def __init__(self, panels=None, title=None, submit_text="Create", **kwargs):
        super().__init__(macro_type="wizard", **kwargs)

        self._panels = []
        self._active_index = 0
        self._set_state(title=title, submit_text=submit_text)

        self._create_event('submit')
        self._create_event('panel_change')

        self._init_macro()

        for panel in (panels or []):
            self.add_panel(panel)
        self._show_panel(0)

    def _create_elements(self):
        container = self._register_element('container', self._create_container({
            "border": "1px solid #ddd", "border-radius": "8px",
            "background-color": "#fff", "overflow": "hidden",
            "margin-top": "20px",
        }))

        title = self._get_state('title')
        if title:
            container.add(Div(title, style={
                "padding": "12px 16px", "font-weight": "600",
                "background-color": "#2c3e50", "color": "#fff",
            }))

        _ensure_css()

        sidebar = self._register_element('sidebar', Div(style={
            "width": "160px", "flex-shrink": "0",
            "border-right": "1px solid #e9ecef", "background-color": "#f8f9fa",
            "padding": "8px 0",
        }))
        sidebar.set_attribute("class", "wizard-sidebar")
        content = self._register_element('content', Div(style={
            "flex": "1", "padding": "16px", "min-width": "0",
        }))

        body = Div(sidebar, content, style={
            "display": "flex", "flex-wrap": "wrap", "align-items": "stretch",
        })
        body.set_attribute("class", "wizard-body")

        submit = self._register_element('submit', Button(self._get_state('submit_text'), style={
            "background-color": "#0066cc", "color": "#fff", "border": "none",
            "padding": "8px 18px", "border-radius": "4px", "cursor": "pointer",
            "font-size": "14px",
        }))
        # Element.on() makes its own proxy, so hand it the plain callable.
        submit.on_click(lambda e: self._fire_event('submit'))

        status = self._register_element('status', Span("", style={
            "margin-left": "12px", "font-size": "13px", "color": "#b00020",
        }))

        footer = Div(submit, status, style={
            "padding": "12px 16px", "border-top": "1px solid #e9ecef",
            "background-color": "#f8f9fa", "display": "flex", "align-items": "center",
        })

        container.add(body, footer)
        return container

    def _nav_button(self, panel, index):
        button = Button(panel.title, style={
            "display": "block", "width": "100%", "text-align": "left",
            "padding": "10px 16px", "border": "none", "background": "transparent",
            "cursor": "pointer", "font-size": "14px", "color": "#495057",
            "border-left": "3px solid transparent",
        })
        button.on_click(lambda e, i=index: self._show_panel(i))
        return button

    def _show_panel(self, index):
        if not (0 <= index < len(self._panels)):
            return self
        self._active_index = index

        for i, panel in enumerate(self._panels):
            active = i == index
            panel.content.style.display = "block" if active else "none"
            if panel.nav_button:
                panel.nav_button.style.background_color = "#fff" if active else "transparent"
                panel.nav_button.style.color = "#212529" if active else "#495057"
                panel.nav_button.style.border_left = (
                    "3px solid #0066cc" if active else "3px solid transparent"
                )
                panel.nav_button.style.font_weight = "600" if active else "400"

        self._fire_event('panel_change', self._panels[index])
        return self

    def add_panel(self, panel):
        index = len(self._panels)
        panel.nav_button = self._nav_button(panel, index)
        self._get_element('sidebar').add(panel.nav_button)

        wrapper = Div(style={"display": "none"})
        if panel.description:
            wrapper.add(Div(panel.description, style={
                "color": "#6c757d", "font-size": "13px", "margin-bottom": "14px",
            }))
        wrapper.add(panel.content)

        # _show_panel toggles this wrapper, so keep it as the panel's element
        panel.content = wrapper
        self._get_element('content').add(wrapper)

        self._panels.append(panel)
        return self

    def set_status(self, message, is_error=True):
        status = self._get_element('status')
        status.set_text(message)
        status.style.color = "#b00020" if is_error else "#146c2e"
        return self

    def set_submit_text(self, text):
        """Change the action button's label, e.g. when a dialog switches mode."""
        self._set_state(submit_text=text)
        self._get_element('submit').set_text(text)
        return self

    def set_busy(self, busy, busy_text="Working…"):
        submit = self._get_element('submit')
        submit._dom_element.disabled = bool(busy)
        submit.set_text(busy_text if busy else self._get_state('submit_text'))
        return self

    @property
    def panels(self):
        return list(self._panels)

scripts/workflow_lib/workflow.py:
"""
The workflow data model: steps and the edits that keep them consistent.

Each step and the spreadsheet can also have a position on the canvas (`layout`);
it is only where a node is drawn and has no effect on what runs. Steps that came
from one tool share a `group`, which the canvas draws as a frame around them; it
too changes nothing about what runs.

A step reads from one or more *sources* — DATA (the spreadsheet) or an earlier
step — through the named input ports of its node. The list order is always a
valid run order: every step comes after each step it reads. All the editing
methods preserve that, which is what lets the engine run the list top to bottom
without sorting it.
"""
from dataclasses import dataclass, field

from .types import TABLE

DATA = "data"


def snap_to_grid(value, grid):
    """`value` moved to the nearest multiple of `grid` (a whole number of pixels)."""
    return round(float(value) / grid) * grid
FORMAT_VERSION = 2


def split_source(source):
    """
    ("step id", "output name") of a source. A step's first output is addressed by
    the step alone ("s3"); another is addressed "s3.weights".
    """
    step_id, _, name = source.partition(".")
    return step_id, name


def step_of(source):
    """The id of the step (or DATA) that a source comes from."""
    return source.partition(".")[0]


def source_ref(step_id, name=""):
    return f"{step_id}.{name}" if name else step_id


class WorkflowError(ValueError):
    """An edit or a document that would break the workflow's structure."""


@dataclass
class Step:
    id: str
    tool: str
    options: dict
    inputs: dict = field(default_factory=dict)   # port name -> [source ids]
    title: str = ""
    group: str = ""                              # the tool it was added with, if any

    @property
    def sources(self):
        """Every source this step reads, in port order, without repeats."""
        found = []
        for ids in self.inputs.values():
            for source in ids:
                if source not in found:
                    found.append(source)
        return found

    @property
    def source_steps(self):
        """The steps (or DATA) those sources come from, without repeats."""
        found = []
        for source in self.sources:
            if step_of(source) not in found:
                found.append(step_of(source))
        return found

    def to_dict(self):
        document = {"id": self.id, "tool": self.tool, "title": self.title,
                    "inputs": {port: list(ids) for port, ids in self.inputs.items()},
                    "options": self.options}
        if self.group:
            document["group"] = self.group
        return document


def _clean_inputs(inputs):
    """A port -> [ids] dict, whatever sloppy shape it was given in."""
    if inputs is None:
        return {}
    cleaned = {}
    for port, ids in dict(inputs).items():
        if isinstance(ids, str):
            ids = [ids]
        cleaned[str(port)] = [str(i) for i in ids]
    return cleaned


@dataclass
class Workflow:
    steps: list = field(default_factory=list)
    layout: dict = field(default_factory=dict)    # id (or DATA) -> [x, y]
    groups: dict = field(default_factory=dict)    # group id -> {"tool": key, "title": text}
    snap_grid: int = 0                            # blocks snap to multiples of this many pixels; 0 is off

    # ---------------------------------------------------------------- queries

    def get(self, step_id):
        for step in self.steps:
            if step.id == step_id:
                return step
        raise WorkflowError(f"No step '{step_id}'.")

    def index_of(self, step_id):
        return self.steps.index(self.get(step_id))

    def numbers(self):
        """
        The number each step goes by, from how the steps fork: those reading the spreadsheet are
        1, 2, 3 in the order they were made; the first step reading step 1 is 1.1, the second 1.2;
        the first reading 1.1 is 1.1.1; and so on. A step that reads several others is numbered
        under the first of them (the first input port), so every step has one place in the tree.

        Derived from the wiring each time, so rewiring or deleting a step renumbers what follows
        it rather than leaving gaps.

        Returns:
            {step id: "1", "1.1", ...}
        """
        label = {DATA: ""}
        children = {}
        for step in self.steps:
            parent = step_of(step.sources[0]) if step.sources else DATA
            if parent not in label:           # reads a step that is not (or not yet) there
                parent = DATA
            children[parent] = children.get(parent, 0) + 1
            label[step.id] = (f"{label[parent]}." if label[parent] else "") + str(children[parent])
        del label[DATA]
        return label

    def dependents(self, step_id):
        """Ids of every step that reads this one, directly or through others."""
        found = []
        frontier = {step_id}
        for step in self.steps:           # list order is run order
            if frontier.intersection(step.source_steps):
                found.append(step.id)
                frontier.add(step.id)
        return found

    def type_of(self, source_id, specs):
        """The data type a source delivers: a table for DATA, else that output of its node."""
        if source_id == DATA:
            return TABLE
        step_id, name = split_source(source_id)
        step = self.get(step_id)
        spec = specs.get(step.tool)
        return spec.type_of_output(name, step.options) if spec else None

    def sources_for(self, specs, port, before=None):
        """
        Sources that `port` could read: DATA, and each output of an earlier step
        whose type the port accepts (a step with several outputs may offer more
        than one, the first as the step's id and the others as "id.name").

        Args:
            specs: {tool key: NodeSpec}
            before: only steps ahead of this step id (for re-pointing a step)
        """
        limit = self.index_of(before) if before else len(self.steps)
        found = [DATA] if port.accepts(TABLE) else []
        for step in self.steps[:limit]:
            spec = specs.get(step.tool)
            for name in (spec.output_names() if spec else []):
                if port.accepts(spec.type_of_output(name, step.options)):
                    found.append(source_ref(step.id, name))
        return found

    # ------------------------------------------------------------------ edits

    def new_group(self, tool, title):
        """Start a group for the steps one tool is about to add; returns its id."""
        numbers = [int(g[1:]) for g in self.groups if g[1:].isdigit()]
        group = f"g{max(numbers, default=0) + 1}"
        self.groups[group] = {"tool": tool, "title": title}
        return group

    def members(self, group):
        """Ids of the steps in a group, in run order."""
        return [step.id for step in self.steps if step.group == group]

    def add(self, tool, options, inputs=None, title="", group=""):
        """Append a step. Each source must be DATA or an existing step."""
        inputs = _clean_inputs(inputs)
        for source in (s for ids in inputs.values() for s in ids):
            if source != DATA:
                self.get(step_of(source))     # raises if it does not exist
        if group and group not in self.groups:
            raise WorkflowError(f"No group '{group}'.")
        step = Step(self._next_id(), tool, dict(options), inputs, title, group)
        self.steps.append(step)
        return step

    def position(self, node_id):
        """Where a node is drawn on the canvas, as (x, y), or None if unplaced."""
        spot = self.layout.get(node_id)
        return (spot[0], spot[1]) if spot else None

    def set_position(self, node_id, x, y):
        """Where a node is drawn; on the grid when snapping is on."""
        if node_id != DATA:
            self.get(node_id)
        if self.snap_grid:
            x, y = snap_to_grid(x, self.snap_grid), snap_to_grid(y, self.snap_grid)
        self.layout[node_id] = [float(x), float(y)]

    def set_snap(self, grid):
        """
        Turn grid snapping on (`grid` pixels, a positive whole number) or off (0). Turning it on
        moves every block placed so far onto the grid.
        """
        self.snap_grid = max(0, int(grid or 0))
        if self.snap_grid:
            for node_id, (x, y) in list(self.layout.items()):
                self.layout[node_id] = [float(snap_to_grid(x, self.snap_grid)),
                                        float(snap_to_grid(y, self.snap_grid))]

    def ancestors(self, step_id):
        """Ids this step reads, directly or through others (DATA excluded)."""
        found = []
        frontier = [step_id]
        while frontier:
            step = self.get(frontier.pop())
            for source in step.source_steps:
                if source != DATA and source not in found:
                    found.append(source)
                    frontier.append(source)
        return found

    def depth_of(self, node_id):
        """How many steps lie between the spreadsheet and this node (DATA is 0)."""
        if node_id == DATA:
            return 0
        step = self.get(node_id)
        return 1 + max((self.depth_of(s) for s in step.source_steps), default=0)

    def remove(self, step_id):
        """
        Remove a step and everything that reads it, since a step without its
        input has nothing to run on.

        Returns the ids removed, the step itself first.
        """
        self.get(step_id)
        removed = [step_id] + self.dependents(step_id)
        self.steps = [s for s in self.steps if s.id not in removed]
        for gone in removed:
            self.layout.pop(gone, None)
        for group in [g for g in self.groups if not self.members(g)]:
            del self.groups[group]          # a frame with nothing in it
        return removed

    def replace(self, step_id, options=None, inputs=None, title=None):
        """Change a step's options, inputs or title in place."""
        step = self.get(step_id)
        if inputs is not None:
            inputs = _clean_inputs(inputs)
            for source in (s for ids in inputs.values() for s in ids):
                self._check_source(step, source)
            step.inputs = inputs
        if options is not None:
            step.options = dict(options)
        if title is not None:
            step.title = title
        return step

    # ----------------------------------------------------------- canvas wiring
    # The canvas lets a wire go to any step that would not make a loop, wherever
    # it sits in the list; the list is put back into run order afterwards.

    def can_connect(self, specs, source_id, step_id, port_name):
        """May `source_id` feed `port_name` of `step_id` — right type, no loop?"""
        step = self.get(step_id)
        spec = specs.get(step.tool)
        if spec is None or step_of(source_id) == step_id:
            return False
        try:
            port = spec.port(port_name)
        except KeyError:
            return False
        if source_id != DATA:
            self.get(step_of(source_id))
            if step_of(source_id) in self.dependents(step_id):
                return False
        return port.accepts(self.type_of(source_id, specs))

    def connect(self, specs, source_id, step_id, port_name):
        """
        Wire a source into a port: a port that takes one source switches to it,
        one that takes several adds it. Returns the inputs the step now has.

        Raises:
            WorkflowError: if the type does not fit or the wire would make a loop
        """
        if not self.can_connect(specs, source_id, step_id, port_name):
            raise WorkflowError(
                f"'{source_id}' cannot feed '{port_name}' of '{step_id}': "
                "wrong kind of data, or it would make a loop.")
        step = self.get(step_id)
        port = specs[step.tool].port(port_name)
        current = list(step.inputs.get(port_name, []))
        if port.multiple:
            if source_id not in current:
                current.append(source_id)
        else:
            current = [source_id]
        self.rewire(step_id, {**step.inputs, port_name: current})
        return self.get(step_id).inputs

    def disconnect(self, step_id, port_name, source_id):
        """Take one wire off a port; the port may be left empty."""
        step = self.get(step_id)
        remaining = [s for s in step.inputs.get(port_name, []) if s != source_id]
        self.rewire(step_id, {**step.inputs, port_name: remaining})

    def rewire(self, step_id, inputs):
        """
        Replace a step's inputs, allowing sources that come later in the list.

        The list is then reordered so every step still follows what it reads,
        changing as little as it can.

        Raises:
            WorkflowError: for an unknown source or one that would make a loop
        """
        step = self.get(step_id)
        inputs = _clean_inputs(inputs)
        for source in (s for ids in inputs.values() for s in ids):
            if source == DATA:
                continue
            self.get(step_of(source))
            if step_of(source) == step_id or step_of(source) in self.dependents(step_id):
                raise WorkflowError(f"A step cannot read '{source}': that would make a loop.")
        step.inputs = inputs
        self._resort()

    def _resort(self):
        """
        Put the list back in run order, disturbing it as little as possible: walk
        it as it stands, and where a step reads one that comes later, bring that
        one (and what it needs) forward just ahead of it.
        """
        by_id = {step.id: step for step in self.steps}
        ordered, done, visiting = [], set(), set()

        def place(step):
            if step.id in done:
                return
            if step.id in visiting:
                raise WorkflowError("The steps contain a loop.")
            visiting.add(step.id)
            for source in step.source_steps:
                if source != DATA:
                    place(by_id[source])
            visiting.discard(step.id)
            done.add(step.id)
            ordered.append(step)

        for step in self.steps:
            place(step)
        self.steps = ordered

    def move(self, step_id, delta):
        """
        Shift a step up (negative) or down (positive) the list.

        Refused, returning False, if that would put a step ahead of one it
        reads or behind one that reads it.
        """
        index = self.index_of(step_id)
        target = index + delta
        if target < 0 or target >= len(self.steps):
            return False
        proposed = list(self.steps)
        proposed.insert(target, proposed.pop(index))
        if not self._ordered(proposed):
            return False
        self.steps = proposed
        return True

    def _check_source(self, step, new_source):
        """Raise unless `step` may read `new_source` without a cycle or a gap."""
        if new_source == DATA:
            return
        source = self.get(step_of(new_source))
        if source.id == step.id or step.id in self.dependents(source.id) \
                or self.index_of(source.id) > self.index_of(step.id):
            raise WorkflowError(
                f"A step cannot read '{new_source}': it comes later or reads this step.")

    @staticmethod
    def _ordered(steps):
        seen = {DATA}
        for step in steps:
            if any(source not in seen for source in step.source_steps):
                return False
            seen.add(step.id)
        return True

    def _next_id(self):
        numbers = [int(s.id[1:]) for s in self.steps
                   if s.id.startswith("s") and s.id[1:].isdigit()]
        return f"s{max(numbers, default=0) + 1}"

    # ------------------------------------------------------------ persistence

    def to_dict(self):
        document = {"version": FORMAT_VERSION,
                    "steps": [step.to_dict() for step in self.steps]}
        known = {DATA} | {step.id for step in self.steps}
        layout = {key: list(spot) for key, spot in self.layout.items() if key in known}
        if layout:
            document["layout"] = layout
        groups = {g: dict(info) for g, info in self.groups.items() if self.members(g)}
        if groups:
            document["groups"] = groups
        if self.snap_grid:
            document["snap"] = self.snap_grid
        return document

    @classmethod
    def from_dict(cls, document):
        """
        Rebuild from `to_dict` output.

        Raises:
            WorkflowError: for anything that is not a well-formed, correctly
                ordered workflow, including one saved before steps had typed
                inputs
        """
        if not isinstance(document, dict) or not isinstance(document.get("steps"), list):
            raise WorkflowError("A workflow needs a list of steps.")
        if document.get("version") != FORMAT_VERSION:
            raise WorkflowError(
                "This workflow was saved by an older version, before analyses "
                "could be chained by data type, and cannot be loaded.")
        steps = []
        for raw in document["steps"]:
            if (not isinstance(raw, dict) or not isinstance(raw.get("id"), str)
                    or not isinstance(raw.get("tool"), str)
                    or not isinstance(raw.get("options"), dict)
                    or not isinstance(raw.get("inputs", {}), dict)):
                raise WorkflowError("A step needs an id, a tool, inputs and options.")
            steps.append(Step(raw["id"], raw["tool"], dict(raw["options"]),
                              _clean_inputs(raw.get("inputs")),
                              str(raw.get("title") or ""), str(raw.get("group") or "")))
        if len({s.id for s in steps}) != len(steps):
            raise WorkflowError("Step ids must be unique.")
        if not cls._ordered(steps):
            raise WorkflowError("A step reads a step that does not come before it.")
        layout = {}
        raw_layout = document.get("layout")
        if isinstance(raw_layout, dict):
            known = {DATA} | {step.id for step in steps}
            for key, spot in raw_layout.items():
                if (key in known and isinstance(spot, (list, tuple)) and len(spot) == 2
                        and all(isinstance(v, (int, float)) and not isinstance(v, bool)
                                for v in spot)):
                    layout[key] = [float(spot[0]), float(spot[1])]
        groups = {}
        raw_groups = document.get("groups")
        if isinstance(raw_groups, dict):
            for key, info in raw_groups.items():
                if isinstance(info, dict) and any(s.group == key for s in steps):
                    groups[str(key)] = {"tool": str(info.get("tool", "")),
                                        "title": str(info.get("title", ""))}
        for step in steps:
            if step.group not in groups:
                step.group = ""
        snap = document.get("snap")
        grid = snap if isinstance(snap, int) and not isinstance(snap, bool) and snap > 0 else 0
        return cls(steps, layout, groups, grid)
